  function select(cards, text, options={}) {
    const ctx=context(text,cards,options),rows=[];
    for(const c of cards) {const result=scoreCard(c,ctx);if(result.score>0&&content(c))rows.push({card:c,...result});}
    rows.sort((a,b)=>b.score-a.score||b.card.updatedAt-a.card.updatedAt||a.card.id.localeCompare(b.card.id));
    // Latest explicit state wins for one person's outfit and one directed speech pair.
    const current=new Map();
    for(const row of rows) if(['speech','outfit','health'].includes(row.card.kind)&&row.card.subject){
      const key=[row.card.kind,row.card.subject,row.card.target||'',row.card.timeline].join('|');
      const old=current.get(key);if(!old||old.card.updatedAt<row.card.updatedAt)current.set(key,row);
    }
    const accepted=rows.filter(r=>!['speech','outfit','health'].includes(r.card.kind)||!r.card.subject||current.get([r.card.kind,r.card.subject,r.card.target||'',r.card.timeline].join('|'))===r);
    const seen=new Set(),deduped=[];
    for(const row of accepted){const fingerprint=[row.card.kind,row.card.subject,row.card.target,row.card.visibility,list(row.card.knowers).sort().join(','),content(row.card).replace(/\s+/g,'')].join('|');if(!seen.has(fingerprint)){seen.add(fingerprint);deduped.push(row);}}
    return {rows:deduped,active:[...ctx.active]};
  }
  function toItem(row) {const c=row.card;return {slotId:'suite:'+c.id,group:'suite-'+c.kind,title:KINDS[c.kind]+' · '+c.title,content:content(c),totalTurns:0,usedTurns:0,
    autoType:'suite',suiteKind:c.kind,sourceKey:c.id,recallScore:row.score,recallReason:row.reason,suitePinned:c.mode==='always',suiteVersion:c.updatedAt};}
  function digest(cards) {return cards.map(c=>({id:c.id,kind:c.kind,title:c.title,subject:c.subject,target:c.target,locked:c.locked,status:c.status,stale:!!c.stale,aliases:c.aliases||[],owner:c.owner,holder:c.holder,lifecycle:c.lifecycle,storyDate:c.storyDate,storyDay:c.storyDay,text:content(c).slice(0,1600)}));}
