  externalAll:'wish',externalRelationships:'wish',externalSecondary:'wish',
  ai:'shared',advanced:'shared',ePack:'lore',eEntry:'lore',
  loreConvert:'lore',loreSplit:'lore',
  suiteRecords:'shared',suiteTasks:'shared',suiteTimeline:'wish',
  suiteLore:'lore',suiteRefiner:'wish',suiteLegacy:'wish',
  'task:currentState':'wish','task:event':'wish','task:scene':'wish',
  'task:lore':'lore','task:place':'lore','task:item':'lore',
