            if (!(await showUiConfirm('현재 채팅의 자동 요약 기준점, 관리 이력, 자동 AI 비용 기록을 초기화할까요?\n저장된 장기기억 카드는 삭제하지 않습니다.', '자동 요약 기준점 초기화', { confirmText:'초기화', tone:'warning' }))) return;
            resetAutoMemoryState(resetChatId);
