    const anchor = cursor ? turns.findIndex(turn => String(turn.key) === cursor) : -1;
    if (!['full','custom'].includes(mode) && cursor && anchor < 0) throw new Error(`${mode === 'manual' ? '수동' : '자동'} 기준 턴이 현재 시간선에 없습니다. 리롤·분기를 확인해 주세요.`);
