      if(jump){const surface=jump.closest('[data-ltm-surface]'),editor=surface.querySelector('[data-ltm-import-text]'),report=longTermResultReports.get(longTermResultReportKey(room,surface)),issue=report?.issues[Number(jump.dataset.ltmValidationJump)];if(editor&&issue){editor.focus({preventScroll:true});editor.setSelectionRange(issue.start,issue.end);editor.scrollTop=Math.max(0,(issue.line-2)*parseFloat(getComputedStyle(editor).lineHeight||'22'));editor.scrollIntoView({block:'nearest'});}return;}
      const tab=event.target.closest?.('[data-ltm-surface] [data-ltm-tab]');
