      if(!batch.length){wsSetStatus(manual?'새로 정리할 완료 대화가 없습니다.':'아직 묶음 주기에 도달하지 않았습니다. 최신 1턴은 다음 답변 뒤 정리합니다.');return;}
      const catalog=d.cards.filter(c=>!c.timeline||c.timeline===timeline),inventory=wsBoundedInventory(catalog,batch.map(t=>t.text).join('\n'),room);
      const stateBefore=String(wsStateSlot(room)?.content||''),stateToken=wsCore.hash(stateBefore+'|'+timeline+'|'+taskStamp),guide=wsExtractionGuide(plan.tasks);
      const coreReference=await WSUITE.host.reference(room);wsAssertActive(room,timeline,taskStamp,basis);
      const prompt=JSON.stringify({readOnlyCore:coreReference,timeline,scene:sceneBefore,userName:d.settings.userName,taskRanges:Object.fromEntries(Object.entries(plan.tasks).map(([id,p])=>[id,p.ids])),existing:inventory.full,catalogIndex:inventory.index,catalogScope:inventory.scope,
        ...(plan.tasks.currentState?{currentState:stateBefore,stateBaseToken:stateToken}:{}),fixed:room.slots.filter(s=>s.enabled&&['character','extra'].includes(s.group)).map(s=>({title:s.title,content:s.content})),dialogue:batch.map(t=>({id:t.key,text:t.text}))});
      assertAiRequestFits(guide,prompt,'기억·인물 통합 정리');
      wsSetStatus(Object.keys(plan.tasks).length+'개 세부 작업 · 공유 원문 '+batch.length+'턴 · AI 1회 요청 중…');
      const result=await wsAi(room,guide+'\nreadOnlyCore는 기존 Core 기록이다. 변경 대상이 아니며 이미 같은 내용이 있는 정보를 변화 없이 새 카드로 복제하지 않는다. 변경 근거는 dialogue에서만 찾는다.',prompt,'context');
