      const scoped=wsScopedPatch(wsCore.parseJson(result.text),plan.tasks,catalog),raw=scoped.raw;
      const fullIds=new Set(inventory.full.map(c=>c.id));
      if([...raw.upserts,...raw.retire].some(r=>r.id&&!fullIds.has(String(r.id))))throw new Error('본문이 제공되지 않은 기존 카드의 수정입니다. 원본을 유지합니다.');
      const patch=wsCore.validatePatch(raw,catalog,batch,timeline);
      if(patch.upserts.some(p=>p.before&&!fullIds.has(p.before.id)))throw new Error('본문을 받지 않은 기존 정보를 새 ID로 우회 수정할 수 없습니다.');
      if(plan.tasks.currentState&&!raw.state)throw new Error('현재상태 작업 결과가 누락됐습니다. 이어 읽기 기준을 이동하지 않았습니다.');
      if(raw.state){const p=wsCore.stateDelta(stateBefore,raw.state,batch.filter(t=>plan.tasks.currentState.ids.includes(t.key)),stateToken);if(p.edits.length)patch.state=p;}
      if(raw.scene?.evidence){const t=batch.find(t=>String(t.key)===String(raw.scene.sourceTurn));if(!t||String(raw.scene.evidence).trim().length<4||!t.text.replace(/\s+/g,' ').includes(String(raw.scene.evidence).trim().replace(/\s+/g,' ')))throw new Error('작품 날짜·일차의 원문 근거를 확인할 수 없습니다.');if(raw.scene.date&&!t.text.includes(String(raw.scene.date).trim()))throw new Error('작품 날짜는 원문 표기 그대로만 갱신할 수 있습니다.');if(raw.scene.day!=null&&!t.text.includes(String(raw.scene.day)))throw new Error('작품 일차를 원문에서 확인할 수 없습니다.');patch.scene={date:String(raw.scene.date||sceneBefore.date||'').slice(0,120),day:raw.scene.day==null?sceneBefore.day:Math.max(0,Math.floor(Number(raw.scene.day)||0)),sourceTurn:String(raw.scene.sourceTurn),evidence:String(raw.scene.evidence),before:sceneBefore};}
      // A no-change response advances cursors too: validate sources before ANY progress commit.
      const latest=await fetchAiMessageHistory(apiChatIdOf(room),'',500),live=new Map(buildCompletedAiDialogueTurns(latest).map(t=>[t.key,t]));
