      d.draft={patch,tasks:plan.tasks,lastKey:batch.at(-1).key,timeline,sourceHashes:Object.fromEntries(batch.map(t=>[t.key,wsCore.hash(t.text)])),createdAt:Date.now(),notices:scoped.notices};
