    const notices=[],out={...raw,upserts:[],retire:[]},byId=new Map(catalog.map(c=>[c.id,c]));
    const allow=(id,row)=>{if(!plan[id]){notices.push((WS_TASK_LABELS[id]||id)+' · 요청하지 않은 작업 결과 제외');return false;}
      if(!plan[id].ids.includes(String(row.sourceTurn)))throw new Error(WS_TASK_LABELS[id]+'에 다른 작업 범위의 원문이 사용됐습니다.');return true;};
    for(const row of raw.upserts){if(!row||!Object.hasOwn(wsCore.KINDS,row.kind))throw new Error('지원하지 않는 정보 종류입니다.');if(allow(row.kind,row))out.upserts.push(row);}
    for(const row of raw.retire){const old=byId.get(String(row?.id));if(!old)throw new Error('폐기 대상 ID를 찾을 수 없습니다.');if(allow(old.kind,row))out.retire.push(row);}
    if(raw.scene){if(!plan.scene){delete out.scene;notices.push('작품 시점 · 요청하지 않은 결과 제외');}else if(!plan.scene.ids.includes(String(raw.scene.sourceTurn)))throw new Error('작품 시점 근거가 해당 작업 범위에 없습니다.');}
