      const oldCounts=new Map(),newCounts=new Map();for(const b of blocks)oldCounts.set(b.key,(oldCounts.get(b.key)||0)+1);for(const b of parsed)newCounts.set(b.key,(newCounts.get(b.key)||0)+1);
