      if(unexpected(originalError)||!options.allowPartial||!p.memory||!p.observe)throw originalError;
      if(!data||typeof data!=='object'||Array.isArray(data)||data.schema_version!=='1'||Object.keys(data).some(k=>!['schema_version','memory','observe'].includes(k)))throw originalError;
      if(req.stateDelta&&(!WishEconomy.settings(room).delta||JSON.stringify(inventory(room,cog,packs))!==JSON.stringify(req.db)))throw originalError;
