  // Crack API
  // ---------------------------------------------------------------------------

  // Reuse only the site's own access cookie. No refresh endpoint, credential
  // persistence or intercepted request headers are needed for auth recovery.
  const crackAuthState={waiting:null,failures:0,retryAt:0,code:'',cookieStamp:'',watchTimer:0,wakeTimer:0};
  const crackAuthDelays=[5000,15000,30000,60000,120000,300000];
  function readCrackAccessToken(){
    let cookie='';try{cookie=document.cookie||'';}catch{}
    const candidates=[],seen=new Set();
    for(const part of cookie.split(';')){
      const m=part.trim().match(/^access_token=(.*)$/);if(!m)continue;
      let value;try{value=decodeURIComponent(m[1]).trim();}catch{continue;}
      if(!value||/^(?:null|undefined)$/i.test(value)||/[\s\r\n]/.test(value)||seen.has(value))continue;
      seen.add(value);let exp=0,iat=0;
      // Claims only order duplicate cookies; the server still authenticates them.
      try{const payload=value.split('.')[1];if(payload){const claims=JSON.parse(atob(payload.replace(/-/g,'+').replace(/_/g,'/')));exp=Number(claims.exp)||0;iat=Number(claims.iat)||0;}}catch{}
      candidates.push({value,exp,iat,index:candidates.length});
    }
    const now=Date.now()/1000;
    candidates.sort((a,b)=>Number(!!a.exp&&a.exp<=now)-Number(!!b.exp&&b.exp<=now)||b.iat-a.iat||a.index-b.index);
    return candidates[0]?.value||'';
  }
  function isCrackAuthError(error){
    const code=String(error?.code||''),message=String(error?.message||error||'');
    return /^CRACK_AUTH_/.test(code)||/사이트 로그인 확인 대기|로그인 토큰을 찾지 못했습니다|크랙 로그인 정보를 읽지 못했습니다/.test(message);
  }
  function crackAuthWake(){
    if(crackAuthState.wakeTimer)return;
    crackAuthState.wakeTimer=setTimeout(()=>{
      crackAuthState.wakeTimer=0;if(document.hidden||navigator.onLine===false)return;
      const r=state.currentRoom;if(!r)return;
      U3.wake(r,'auth-ready');scheduleRecovery(0);renderModalIfIdle();
    },0);
  }
  function refreshCrackAuthCookie(){
    const token=readCrackAccessToken(),stamp=token?aiHashTiny(token):'';
    if(stamp!==crackAuthState.cookieStamp){
      const waiting=!!crackAuthState.code;
      crackAuthState.cookieStamp=stamp;crackAuthState.failures=0;crackAuthState.retryAt=0;
      if(waiting&&token)crackAuthWake();
    }
    return token;
  }
  function watchCrackAuth(){
    if(crackAuthState.watchTimer||document.hidden||navigator.onLine===false)return;
    if(!crackAuthState.code&&!isCrackAuthError(state.currentRoom?.unified?.lastError))return;
    crackAuthState.watchTimer=setTimeout(()=>{
      crackAuthState.watchTimer=0;if(document.hidden||navigator.onLine===false)return;
      refreshCrackAuthCookie();watchCrackAuth();
    },2000);
  }
  function crackAuthError(code,options={}){
    const token=refreshCrackAuthCookie(),stamp=crackAuthState.cookieStamp;
    // A response sent with an old cookie cannot reject a newer login session.
    const stale=options.stamp!==undefined&&options.stamp!==stamp&&!!token;
    if(!stale){
      if(Date.now()>=crackAuthState.retryAt){
        crackAuthState.failures=Math.min(crackAuthDelays.length,crackAuthState.failures+1);
        crackAuthState.retryAt=Date.now()+crackAuthDelays[crackAuthState.failures-1];
      }
      crackAuthState.code=code;watchCrackAuth();
    }else crackAuthWake();
    const detail=code==='CRACK_AUTH_REJECTED'?'크랙 서버에서 로그인 정보를 다시 확인해야 합니다.':'사이트의 로그인 정보가 아직 준비되지 않았습니다.';
    return Object.assign(new Error('사이트 로그인 확인 대기 중입니다. '+detail+' 로그인 확인이 되면 밀린 정리를 자동으로 이어갑니다. 크랙에서도 로그인이 풀렸다면 다시 로그인해 주세요.'),{code,authRetryAt:stale?Date.now()+500:crackAuthState.retryAt});
  }
  function crackAuthSuccess(stamp){
    refreshCrackAuthCookie();if(stamp!==crackAuthState.cookieStamp)return;
    const waiting=!!crackAuthState.code;crackAuthState.failures=0;crackAuthState.retryAt=0;crackAuthState.code='';
    clearTimeout(crackAuthState.watchTimer);crackAuthState.watchTimer=0;
    if(waiting)crackAuthWake();
  }
  async function waitForCrackToken(){
    let token=refreshCrackAuthCookie();
    if(Date.now()<crackAuthState.retryAt)throw crackAuthError(crackAuthState.code||'CRACK_AUTH_MISSING');
    if(token)return token;
    if(crackAuthState.waiting)return crackAuthState.waiting;
    const work=(async()=>{
      for(const delay of [250,500,1000,2000]){await new Promise(resolve=>setTimeout(resolve,delay));const value=refreshCrackAuthCookie();if(value)return value;}
      throw crackAuthError('CRACK_AUTH_MISSING');
    })();crackAuthState.waiting=work;
    try{return await work;}finally{if(crackAuthState.waiting===work)crackAuthState.waiting=null;}
  }
  function pendingSyncIssue(pending){
    const error=String(pending?.lastSyncError||'');
    return {error,authWaiting:!!error&&isCrackAuthError({code:pending?.lastSyncErrorCode,message:error}),lastCheckedAt:Number(pending?.verifiedAt||0)};
  }
  function recordPendingSyncError(room,error){
    if(!room?.pending)return;
    room.pending.lastSyncError=String(error?.message||error);
    room.pending.lastSyncErrorCode=String(error?.code||'');
    room.pending.lastSyncErrorAt=Date.now();
  }
  for(const event of ['online','focus'])window.addEventListener(event,()=>{refreshCrackAuthCookie();watchCrackAuth();});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshCrackAuthCookie();watchCrackAuth();}});

  async function apiRequest(method, url, body = undefined, options = {}) {
    const token=await waitForCrackToken(),stamp=aiHashTiny(token);
    return new Promise((resolve, reject) => {
      GM_xmlhttpRequest({
        method,url,
        headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',Accept:'application/json, text/plain, */*',platform:'web','wrtn-locale':'ko-KR'},
        data:body===undefined?undefined:JSON.stringify(body),
        timeout:Math.max(1000,Math.min(120000,Number(options.timeoutMs)||20000)),
        onload:res=>{
          let parsed=null;try{parsed=res.responseText?JSON.parse(res.responseText):null;}catch{}
          if(res.status>=200&&res.status<300){crackAuthSuccess(stamp);resolve(parsed??{ok:true});}
          // Never silently replay a PATCH/POST after an auth error.
          else if(res.status===401)reject(crackAuthError('CRACK_AUTH_REJECTED',{stamp}));
          else{const detail=parsed?.message||parsed?.error||res.responseText?.slice(0,250)||'';reject(new Error(`API 오류 ${res.status}${detail?`: ${detail}`:''}`));}
        },
        ontimeout:()=>reject(new Error('API 요청 시간 초과')),
        onerror:()=>reject(new Error('네트워크 오류')),
      });
    });
  }
  async function fetchRecentMessages(chatId,limit=30) {
    const finish=typeof WishPerformance==='undefined'?()=>{}:WishPerformance.start('recentRead');
    try {
    const data=await apiRequest('GET',`https://crack-api.wrtn.ai/crack-gen/v3/chats/${chatId}/messages?limit=${limit}`);
    const messages=data?.data?.messages??data?.messages;
    if(!Array.isArray(messages)||messages.some(m=>!messageIdOf(m)||!['user','assistant','system'].includes(messageRoleOf(m))))
      throw Error('최근 대화 목록 응답 형식을 확인할 수 없습니다. 기존 기준점은 유지합니다.');
    const ids=messages.map(m=>String(messageIdOf(m)));if(new Set(ids).size!==ids.length)throw Error('최근 대화 목록에 중복 ID가 있습니다.');
    SuiteIntegration.observe(chatId,messages);
    return messages;

    } finally {finish();}
  }

  async function fetchMessage(chatId, messageId) {
    if(!messageId)return null;
    try {
      const url=`https://crack-api.wrtn.ai/crack-gen/v3/chats/${chatId}/messages/${messageId}`;
      const data=await apiRequest('GET',url);return data?.data||data||null;
    } catch(error) {
      if(isCrackAuthError(error))throw error;
      const recent=await fetchRecentMessages(chatId,50),found=recent.find(m=>String(messageIdOf(m))===String(messageId));
      if(found)return found;
      if(!/API 오류 (404|410)/.test(String(error.message||error)))throw error;
      const all=await fetchAllRoomMessages(chatId);return all.find(m=>String(messageIdOf(m))===String(messageId))||null;
    }
  }

  async function patchMessage(chatId, messageId, nextText, expectedCurrentText=null, options={}) {
    await assertActiveRoomLease(chatId);
    if(stripOurContextBlock(nextText).found){
      const frame=stableFrame(await fetchRecentMessages(chatId,12));
      if(generationPending(chatId)||String(messageIdOf(frame.latest))===String(messageId))throw new Error('최신 AI 또는 생성 중인 대화에는 주입할 수 없습니다.');
      if(!frame.stable.some(m=>String(messageIdOf(m))===String(messageId)))throw new Error('주입 대상이 현재 확정 대화에 없습니다.');
    }
    if(expectedCurrentText!==null||stripOurContextBlock(nextText).found){
      const current=await fetchMessage(chatId,messageId);if(!current)throw new Error('수정 대상 메시지가 사라졌습니다.');
      const raw=messageTextOf(current);
      if(expectedCurrentText!==null?raw!==expectedCurrentText:normalizeLineBreaks(stripOurContextBlock(raw).text).trimEnd()!==normalizeLineBreaks(stripOurContextBlock(nextText).text).trimEnd())throw new Error('주입 준비 중 AI 원문이 바뀌었습니다. 최신 원문으로 다시 확인해 주세요.');
    }
    // 폴더의 Crack shared-core/번역기 레퍼런스가 실제 편집에 사용하는 contents-api v3를 우선합니다.
    // crack-gen은 조회에는 쓰이지만 PATCH 2xx 뒤 본문이 바뀌지 않는 경우가 있어 성공 응답만 믿지 않습니다.
    const candidates = [
      ['contents v3',`https://contents-api.wrtn.ai/character-chat/v3/chats/${chatId}/messages/${messageId}`],
      ['crack-gen v3',`https://crack-api.wrtn.ai/crack-gen/v3/chats/${chatId}/messages/${messageId}`],
      ['contents legacy',`https://contents-api.wrtn.ai/character-chat/character-chats/${chatId}/messages/${messageId}`],
    ];
    const errors=[],deadline=Date.now()+30000,left=()=>Math.max(0,deadline-Date.now());
    for (const [label,url] of candidates) {
      if(left()<=0){errors.push('전체 PATCH 복구 제한 시간 30초 초과');break;}
      try {
        if(options.beforeWrite)await options.beforeWrite();
        await apiRequest('PATCH', url, { message: nextText }, {timeoutMs:Math.min(8000,left())});
        // 일부 endpoint는 2xx를 반환하고도 실제 메시지를 바꾸지 않는다. GET으로 직접 확인한
        // 경우에만 성공으로 끝내며, 미반영이면 다음 호환 endpoint를 시도한다.
        let observed='';
        for(let attempt=0;attempt<2;attempt++){
          if(left()<=0)throw new Error('PATCH 반영 확인 제한 시간 30초 초과');
          if(attempt)await sleep(Math.min(300,left()));
          const checked=await apiRequest('GET',`https://crack-api.wrtn.ai/crack-gen/v3/chats/${chatId}/messages/${messageId}`,undefined,{timeoutMs:Math.min(6000,left())});
          observed=messageTextOf(checked?.data||checked||{});
          if(normalizeLineBreaks(observed)===normalizeLineBreaks(nextText))return true;
        }
        errors.push(`${label}: 성공 응답 뒤 서버 본문 미반영`);
      } catch (e) {
        if(isCrackAuthError(e)||e?.code==='WISH_REFINER_STALE')throw e;
        errors.push(`${label}: ${String(e?.message||e)}`);
      }
    }
    throw new Error(`메시지 PATCH 실패 · ${errors.join(' / ')}`);
  }

  async function fetchRoomMeta(chatId) {
    try {
      const data = await apiRequest('GET', `https://crack-api.wrtn.ai/crack-gen/v3/chats/${chatId}`);
      const d = data?.data || data || {};
      if(data?.result&&data.result!=='SUCCESS')return {label:'',characterScopeIds:[]};
      const confirmed=WishRoomNames.accept(d,String(chatId));
      const actualId=String(d?._id||d?.id||'');
      if(actualId&&actualId!==String(chatId))return {label:'',characterScopeIds:[]};
      const label = confirmed?.title || d?.story?.name || d?.character?.name || '';
      const ids = [
        d?.story?._id, d?.story?.id, d?.story?.storyId, d?.story?.characterId, d?.story?.character?._id, d?.story?.character?.id,
        d?.character?._id, d?.character?.id, d?.character?.characterId, d?.characterId, d?.storyId
      ].filter(Boolean).map(String);
      return { label, characterScopeIds: [...new Set(ids)] };
    } catch (_) {
      return { label: '', characterScopeIds: [] };
    }
  }



