    p.recallNeedsRefresh=true;
    const q=context(room,query),epoch=localRestoreEpoch,route=state.routeEpoch,replay=ExternalReplay.revision(apiChatIdOf(room));
    const stamp=()=>JSON.stringify([hybridRecallInputStamp(room),memoryBasis(room),context(room,query)]);
    const before=stamp(),assert=()=>{if(room.pending!==p||state.currentRoom!==room||epoch!==localRestoreEpoch||route!==state.routeEpoch||ExternalReplay.changed(apiChatIdOf(room),replay)||before!==stamp())throw recallStaleError();};
    const previous=new Map((p.items||[]).map(i=>[pendingItemIdentity(i),i]));
    // Keep live slot lifetime and manual overrides. The carrier refresh owns speech/Suite updates.
    const base=(p.items||[]).filter(i=>i.autoType==='suite'||i.autoType==='suite-timeline'||!['log','lore'].includes(injectionCadenceKind(i)));
    const recalled=recall(room,query,base,contextBudgetForCarrier(room,String(options.carrierSource?.originalText||p.originalText||'').length));
