    const last=p.recallPlan,retained=last?.selective&&last.queryHash===aiHashTiny(q)&&last.inventoryHash===aiHashTiny(inventory)&&last.inventoryChars===inventory.length&&last.method==='ai';
    const selection=await chooseAllFitItems(room,candidates,original,q,{selective:true,forceLocal:!options.allowAi||!options.carrierSource,...(retained?{preferredKeys:last.rankedKeys,preferredMethod:'ai'}:{})});
