      space=false;
      if(/["“”„‟❝❞〝〞＂]/u.test(char))pattern+='["“”„‟❝❞〝〞＂]';
      else if(/['‘’‚‛❛❜]/u.test(char))pattern+="['‘’‚‛❛❜]";
