    const actors=actorIds.map(aid=>{const a=live.actors.find(x=>x.id===aid);return a?[a.id,a.name,a.aliases||[],!!a.isPlayer,!!a.archived]:[aid,null];});
    const f=live.facts.find(x=>x.id===c.fact_id);
