    if(!cps.length){q('.two').innerHTML='<p class="empty" style="grid-column:1/-1;padding:40px 16px">아직 정리 기록이 없어요.<br>기억 정리·지금 갱신·재구축 적용 직전에 자동으로 저장돼요.</p>';return;}
    const after=k=>k===0?d.cur:MemoryDiff.snap(cps[k-1]);
