// Read-only presentation of Core records. Never copy these into Suite storage or injection.
function WUIUnifiedInfoCards(room){
  if(room!==state.currentRoom)return [];
  const v=WUIReadModel();if(!v.cog)return [];
  const rows=[],s=x=>String(x??''),add=(kind,id,title,text,action,arg)=>{
    if(!s(text).trim())return;
    rows.push({id:'core-view:'+kind+':'+id,kind,title:s(title),text:s(text),status:'current',updatedAt:0,coreView:true,coreAction:action,coreArg:s(arg)});
  };
  for(const a of v.cog.actors)if(a.aliases.length)add('alias',a.id,a.name,a.aliases.join(' · '),'acEdit',a.id);
  const names=new Map(v.cog.actors.map(a=>[a.id,a.name]));
  for(const f of v.cog.facts){
    const know=Object.entries(f.know||{}).map(([id,k])=>(names.get(id)||id)+' · '+({aware:'알고 있음',unaware:'모름',unverified:'미확인'}[k]||k));
    const con=(f.con||[]).map(c=>(names.get(c.h)||c.h)+' → '+(names.get(c.t)||c.t)+'에게 숨김: '+c.scope+(c.pub?' · 공개명 '+c.pub:''));
    add('knowledge',f.id,f.label||'인지 정보',[f.content,...know,...con].filter(Boolean).join('\n'),'ftEdit',f.id);
  }
  for(const r of v.speech.rows)add('speech',r.id,r.speaker+' → '+r.target,[r.address?'현재 호칭: '+r.address:'호칭 미확정',speechRegisterLabel(r.reg),r.note].filter(Boolean).join('\n'),r.src==='lore'?'spSourceEdit':'spEdit',r.id);
  for(const r of v.relationships.rows)add('relationship',r.id,r.speaker+' → '+r.target,[r.current,r.unresolved?'남은 쟁점: '+r.unresolved:'',r.trajectory?'핵심 전환: '+r.trajectory:''].filter(Boolean).join('\n'),'relEdit',r.id);
  for(const r of v.state.sections){
    // Classify explicit headings only; never extract or invent facts from prose.
    const title=s(r.title),kind=/복장|의상|외형|옷차림|착용/.test(title)?'outfit':/건강|부상|상처|신체/.test(title)?'health':/약속|의무|목표|예정|일정/.test(title)?'promise':'coreState';
    add(kind,r.id,title||'현재 상태',r.body,'stEdit',r.id);
  }
  if(!v.state.sections.length&&v.state.raw.trim())add('coreState','raw','현재 상태',v.state.raw,'raw','state');
  return rows;
}

