function WUIAIConfig(d){const x=d.draft,s=loadAiSettings();return normalizeAiSettings({...s,provider:x.provider,apiKey:x.key?.trim()||s.apiKey,firebaseConfig:x.firebase??s.firebaseConfig,firebaseBackend:x.firebaseBackend,firebaseLocation:x.firebaseLocation,deepSeekApiKey:x.dsKey?.trim()||s.deepSeekApiKey,deepSeekBaseUrl:x.dsBase,model:x.model,geminiThinkingLevel:x.thinking,deepSeekModel:x.dsModel,deepSeekThinking:x.dsThinking!=='0',deepSeekCustomModel:x.dsCustom,openaiApiKey:x.openaiKey?.trim()||s.openaiApiKey,openaiBaseUrl:x.openaiBase,openaiModel:x.openaiModel,vertexJson:x.vertexJson?.trim()||s.vertexJson,vertexLocation:x.vertexLocation,vertexProjectId:x.vertexProject});}

function WUIDateApply(d){const replacements=[];for(const b of d.blocks){if(b.isSpecialDate||b.isYearOnly)continue;const x=d.draft.dn[String(b.index)];if(!x)continue;const y=String(x.y||'').trim()?Number(x.y):null,m=Number(x.m),day=Number(x.d);if(b.isUnknown&&!y&&!m&&!day)continue;if(y!==null&&(!Number.isInteger(y)||y<1||y>999999))throw Error('연도는 1~999999로 입력해 주세요.');if(!Number.isInteger(m)||m<1||m>12||!Number.isInteger(day)||day<1||day>new Date(y||2000,m,0).getDate())throw Error('올바른 월과 일을 입력해 주세요.');if(y!==(b.year||null)||m!==b.month||day!==b.day)replacements.push({start:b.sourceStart,end:b.headingEnd,text:formatNormalizedLogHeading(b,y,m,day)});}if(!replacements.length){notify('변경된 날짜가 없습니다.');return;}let next=d.originalText;replacements.sort((a,b)=>b.start-a.start).forEach(r=>next=next.slice(0,r.start)+r.text+next.slice(r.end));const blocks=parseDatedLogBlocks(next);if(blocks.length!==d.blocks.length)throw Error('날짜 수정 후 블록 수가 달라져 적용을 중단했습니다.');const slot=d.wishRoom.slots.find(s=>s.id==='logSummary');if(slot.content!==d.originalText)throw Error('편집 중 로그가 바뀌었습니다. 다시 열어 주세요.');slot.content=next;remapLogSelectionKeysByIndex(d.wishRoom,d.blocks,blocks);WUIResolve(d.id,true);}
function WUIDedupeApply(d){const selected=new Map();d.originalGroups.forEach((g,i)=>{const chosen=g.blocks.find(b=>String(b.index)===String(d.draft.pick['g'+i])),text=String(d.draft.txt[String(chosen?.index)]||'').trim();if(!chosen||!text)throw Error('남길 로그 내용을 입력해 주세요.');selected.set(g.dateKey,{index:chosen.index,text});});const blocks=parseDatedLogBlocks(d.originalText),parts=[d.originalText.slice(0,blocks[0]?.sourceStart||0).trim()];for(const b of blocks){const c=selected.get(b.dateKey);if(!c)parts.push(b.raw);else if(c.index===b.index)parts.push(c.text);}const slot=d.wishRoom.slots.find(s=>s.id==='logSummary');if(slot.content!==d.originalText)throw Error('편집 중 로그가 바뀌었습니다. 다시 열어 주세요.');slot.content=parts.filter(Boolean).join('\n\n').trim();pruneLogSelectionKeys(d.wishRoom,parseDatedLogBlocks(slot.content));WUIResolve(d.id,true);}
function WUIPresetRoomStamp(room) {
  return JSON.stringify((room?.slots || []).filter(s => s.group === 'extra').map(s =>
    [s.id, s.title, s.content, s.enabled, s.retentionTurns, s.defaultPresetId]));
}
function WUIPresetRoomItems(room) {
  return normalizeExtraPresetItems((room?.slots || []).filter(s => s.group === 'extra' && String(s.content || '').trim())
    .map(s => ({...s, id:s.defaultPresetId}))).map(p => ({...p, ret:String(p.retentionTurns)}));
}
function WUIPresetAssertRoom(d, checkItems = false) {
  if (!d.wishRoom || state.currentRoom !== d.wishRoom || state.routeEpoch !== d.routeEpoch || localRestoreEpoch !== d.restoreEpoch)
    throw Error('방이 바뀌었습니다. 현재 방에서 프리셋을 다시 열어 주세요.');
  if (checkItems && WUIPresetRoomStamp(d.wishRoom) !== d.roomStamp)
    throw Error('편집 중 이 방의 지침이 바뀌었습니다. 이 방 지침으로 교체하거나 프리셋을 다시 열어 주세요.');
}
function WUIPresetAssertStore(d) {
  if (localStorage.getItem(DEFAULT_EXTRA_PRESET_KEY) !== d.storeRaw)
    throw Error('다른 창에서 프리셋이 바뀌었습니다. 프리셋 목록을 다시 열어 주세요.');
}
function WUIPresetPicker(room, mode = 'open') {
  if (!room) throw Error('채팅방을 연 뒤 프리셋을 선택해 주세요.');
  const raw = localStorage.getItem(DEFAULT_EXTRA_PRESET_KEY);
  let store;
  try { store = normalizeDefaultExtraPreset(raw ? JSON.parse(raw) : {}); }
  catch (_) { throw Error('저장된 프리셋을 읽지 못했습니다. 기존 데이터를 확인해 주세요.'); }
  const itemIds = new Set((room.slots || []).filter(s => s.group === 'extra').map(s => s.defaultPresetId).filter(Boolean));
  const linked = store.groups.find(g => g.id === room.extraPresetGroupId) ||
    store.groups.find(g => g.items.some(p => itemIds.has(p.id)));
  return WUI.openSheet('presetPicker', {wishRoom:room, mode, store, storeRaw:raw,
    routeEpoch:state.routeEpoch, restoreEpoch:localRestoreEpoch, roomStamp:WUIPresetRoomStamp(room),
    roomItems:mode === 'save' ? WUIPresetRoomItems(room) : [],
    draft:{selected:linked?.id || (mode === 'open' ? store.defaultGroupId || store.groups[0]?.id : '') || ''}});
}
function WUIPresetOpenGroup(id, create = false) {
  const d = WUI.ui.dlg(id);
  if (!d || d.busy) return;
  WUIPresetAssertRoom(d, d.mode === 'save'); WUIPresetAssertStore(d);
  const group = create ? null : d.store.groups.find(g => g.id === d.draft.selected);
  if (!create && !group) throw Error('프리셋을 선택해 주세요.');
  const list = d.mode === 'save' ? d.roomItems : group?.items || [];
  WUI.closeSheet(d, true);
  return WUI.openSheet('presets', {wishRoom:d.wishRoom, store:d.store, storeRaw:d.storeRaw,
    routeEpoch:d.routeEpoch, restoreEpoch:d.restoreEpoch, roomStamp:d.roomStamp,
    groupId:group?.id || '', fromRoom:d.mode === 'save',
    draft:{name:group?.name || '', isDefault:!!group && d.store.defaultGroupId === group.id,
      list:structuredClone(list).map(p => ({...p, ret:String(p.retentionTurns)}))}});
}
function WUIPresetLoadRoom(id) {
  const d = WUI.ui.dlg(id);
  if (!d || d.busy) return;
  WUIPresetAssertRoom(d);
  if (d.draft.list.length && !confirm('편집 중인 지침 목록 전체를 현재 방의 지침으로 교체할까요?')) return;
  d.draft.list = WUIPresetRoomItems(d.wishRoom);
  d.roomStamp = WUIPresetRoomStamp(d.wishRoom);
  d.fromRoom = true;
}
function WUIPresetDeleteGroup(id) {
  const d = WUI.ui.dlg(id);
  if (!d || d.busy || !d.groupId) return;
  WUIPresetAssertStore(d);
  const group = d.store.groups.find(g => g.id === d.groupId);
  if (!group || !confirm(`‘${group.name}’ 프리셋을 삭제할까요? 방에 적용된 지침은 그대로 남습니다.`)) return;
  saveDefaultExtraPreset({...d.store, groups:d.store.groups.filter(g => g.id !== d.groupId),
    defaultGroupId:d.store.defaultGroupId === d.groupId ? '' : d.store.defaultGroupId}, {expectedRaw:d.storeRaw});
  WUIRefreshSettings(); WUI.closeSheet(d, true);
  notify('프리셋을 삭제했습니다.', 'success');
  if (state.currentRoom) WUIPresetPicker(state.currentRoom);
}
async function WUIPresetsSave(d, apply) {
  if (!d || d.busy) return;
  WUIPresetAssertStore(d);
  WUIPresetAssertRoom(d, apply || d.fromRoom);
  const name = String(d.draft.name || '').trim();
  if (!name || name.length > 100) throw Error('프리셋 이름을 1~100자로 입력해 주세요.');
  const nameKey = s => String(s).normalize('NFKC').toLocaleLowerCase();
  if (d.store.groups.some(g => g.id !== d.groupId && nameKey(g.name) === nameKey(name)))
    throw Error('같은 이름의 프리셋이 있습니다. 다른 이름을 쓰거나 목록에서 해당 프리셋을 골라 덮어써 주세요.');
  if (d.draft.list.length > 50) throw Error('프리셋 하나에는 지침을 최대 50개 저장할 수 있습니다.');
  for (const [i, item] of d.draft.list.entries()) {
    if (!String(item.content || '').trim()) throw Error(`지침 ${i + 1}의 내용을 입력하거나 빈 지침을 삭제해 주세요.`);
    if (String(item.content).length > APP.absoluteUiMax) throw Error(`지침 ${i + 1}의 내용이 최대 ${APP.absoluteUiMax.toLocaleString()}자를 넘습니다.`);
    if (String(item.title || '').trim().length > 100) throw Error(`지침 ${i + 1}의 제목은 100자까지 입력할 수 있습니다.`);
  }
  const items = normalizeExtraPresetItems(d.draft.list.map(x => ({...x, retentionTurns:normalizeRetentionTurns(x.ret)})));
  const group = {id:d.groupId || `group-${crypto.randomUUID()}`, name, updatedAt:nowIso(), items};
  const groups = d.groupId ? d.store.groups.map(g => g.id === d.groupId ? group : g) : [...d.store.groups, group];
  const defaultGroupId = d.draft.isDefault ? group.id : d.store.defaultGroupId === group.id ? '' : d.store.defaultGroupId;
  d.busy = true; WUI.paint();
  let saved = false;
  try {
    d.store = saveDefaultExtraPreset({...d.store, groups, defaultGroupId}, {expectedRaw:d.storeRaw});
    d.storeRaw = localStorage.getItem(DEFAULT_EXTRA_PRESET_KEY);
    d.groupId = group.id; d.fromRoom = false; saved = true;
    WUIRefreshSettings();
    if (apply) {
      const room = d.wishRoom, before = {slots:room.slots, pending:structuredClone(room.pending),
        hadGroup:Object.hasOwn(room, 'extraPresetGroupId'), groupId:room.extraPresetGroupId};
      try {
        applyDefaultExtraPresetToRoom(room, group);
        if (room.pending) { ensureDirectReleasePendingItems(room, room.pending); applyQuickItemSuppression(room.pending); }
        await saveRoom(room);
      } catch (e) {
        room.slots = before.slots; room.pending = before.pending;
        if (before.hadGroup) room.extraPresetGroupId = before.groupId; else delete room.extraPresetGroupId;
        throw e;
      }
      d.roomStamp = WUIPresetRoomStamp(room);
      if (state.currentRoom === room && state.routeEpoch === d.routeEpoch && localRestoreEpoch === d.restoreEpoch)
        await WUISyncMemoryEdit(room);
    }
    d.busy = false; WUIResolve(d.id, true);
    notify(`‘${name}’에 지침 ${items.length}개를 저장했습니다.${apply ? ' 이 방에도 적용했습니다.' : ''}`, 'success');
  } catch (e) {
    if (saved && apply) throw Error('프리셋은 저장했지만 이 방 적용은 완료하지 못했습니다. ' + (e.message || e));
    throw e;
  } finally { d.busy = false; WUI.paint(); }
}


async function WUILoreConvert(d){d.draft.busy=true;WUI.paint();try{const room=d.wishRoom,entries=await convertTextToLoreEntries(d.draft.src),existingPack=(state.v2LorePacks||[]).find(p=>p.scopeId===d.draft.target);if(existingPack?.ownerChatId&&String(existingPack.ownerChatId)!==String(room.chatId||''))throw Error('다른 방 소유 자료집에는 직접 변환 결과를 넣을 수 없습니다. 독립 사본을 만든 뒤 사용해 주세요.');let pack=existingPack?structuredClone(existingPack):null,createdNew=!pack;if(pack){const byKey=new Map(pack.entries.map(e=>[loreEntryMergeKey(e),e]));for(const entry of entries){const old=byKey.get(loreEntryMergeKey(entry));if(old){entry.id=old.id;entry.anchor=entry.speechRule?false:old.anchor||entry.anchor;entry.enabled=old.enabled!==false;}byKey.set(loreEntryMergeKey(entry),entry);}pack.entries=[...byKey.values()];}else pack=normalizeLorePack({name:String(d.draft.name||'가져온 자료집').trim(),entries,ownerChatId:room.chatId,ownerApiChatId:apiChatIdOf(room)});pack=await putLorePack(pack);if(createdNew&&!(room.activeLorePackIds||[]).includes(pack.scopeId))room.activeLorePackIds.push(pack.scopeId);await saveRoom(room);if(room.pending){replaceLorePendingItems(room,room.autoRecallContextText||'',null);await syncPendingCarrier(room,'lore-convert');}notify('자료집 변환 완료 · '+entries.length+'개 자료','success');WUI.closeSheet(d);renderModalIfOpen();}finally{d.draft.busy=false;}}

