// Debounce ordinary edits, and defer saving while an AI commit is protected.
const WUIAutomationSave={timer:null,room:null,changes:{},error:''};
function WUIQueueAutomationSetting(path,value){
 const a=WUIAutomationSave,r=state.currentRoom;if(!r)return;
 a.room=r;a.error='';a.changes[path]=value;WUISettingsDraft()[path]=value;
 if(value===true&&['unified.memoryEnabled','unified.observeEnabled'].includes(path)){
  a.changes['unified.enabled']=true;WUISettingsDraft()['unified.enabled']=true;
 }
 clearTimeout(a.timer);a.timer=setTimeout(()=>void WUIFlushAutomation(),250);
}
async function WUIFlushAutomation(){
 const a=WUIAutomationSave;clearTimeout(a.timer);a.timer=null;
 if(!a.room||!Object.keys(a.changes).length)return;
 const room=a.room;
 if(aiUpdateRunning||SuiteIntegration.busy||memoryImportRunning||localRestoreInProgress()||ExternalReplay.pending(apiChatIdOf(room))){
  a.timer=setTimeout(()=>void WUIFlushAutomation(),1000);return;
 }
 const changes={...a.changes},values={...U3.view(room)};
 for(const [path,value] of Object.entries(changes))values[path.slice('unified.'.length)]=value;
 try{
  await U3.saveSettings(room,values,{quiet:true});
  for(const [path,value] of Object.entries(changes)){
   if(a.changes[path]===value)delete a.changes[path];
   for(const draft of WUICache.settings.values())if(draft[path]===value)delete draft[path];
  }
  a.error='';WUIRefreshSettings();WUI.paint();
 }catch(e){a.error='자동 저장 실패 · '+String(e.message||e);notify(a.error,'error');WUI.paint();}
}
for(const path of ['unified.enabled','unified.memoryEnabled','unified.observeEnabled','unified.memoryEvery','unified.observeEvery'])WUI_ADAPTER.bind[path]=value=>WUIQueueAutomationSetting(path,value);
