  function clipText(text, maxChars, tail = false) {
    const s = String(text || '').trim();
    if (!s) return '';
    if (s.length <= maxChars) return s;
    if (tail) return `[앞부분 ${s.length - maxChars}자 생략]\n` + s.slice(-maxChars);
    return s.slice(0, maxChars) + `\n[이후 ${s.length - maxChars}자 생략]`;
  }

  function loreEntryFull(entry) {
    if (!entry || typeof entry !== 'object') return '';
    const inject = entry.inject && typeof entry.inject === 'object' ? entry.inject : {};
    const summary = entry.summary && typeof entry.summary === 'object' ? entry.summary : {};
    return String(inject.full || summary.full || (typeof entry.summary === 'string' ? entry.summary : '') || entry.full || entry.content || '').trim();
  }

  function searchTerms(text) {
    return [...new Set((String(text || '').normalize('NFKC').toLowerCase().match(/[\p{L}\p{N}_-]+/gu) || [])
      .map(x => x.trim()).filter(x => x.length >= (/^[a-z0-9_-]+$/i.test(x) ? 3 : 2)))].slice(0, 180);
  }

  function loreEntryScore(entry, pool, terms) {
    let score = 0;
    const name = String(entry?.name || '').normalize('NFKC').toLowerCase();
    if (entry?.anchor) score += 10;
    if (entry?.speechRule) score += 8;
    if (entry?.type === 'key_quote') score += 4;
    if (name && pool.includes(name)) score += 8;
    const triggers = Array.isArray(entry?.triggers) ? entry.triggers : [];
    for (const raw of triggers) {
      const trigger = String(raw || '').normalize('NFKC').toLowerCase().trim();
      if (!trigger) continue;
      const parts = trigger.split('&&').map(x => x.trim()).filter(Boolean);
      if (parts.length && parts.every(x => pool.includes(x))) score += 7;
    }
    const entities = Array.isArray(entry?.entities) ? entry.entities : [];
    for (const raw of entities) {
      const entity = String(raw || '').normalize('NFKC').toLowerCase().trim();
      if (entity && pool.includes(entity)) score += 5;
    }
    if (!score && terms.some(t => name.includes(t))) score += 2;
    return score;
  }

  function renderLorePacks(packs, targetText, recentMessages) {
    if (!packs.length) return '(활성 자료팩 없음)';
    const pool = [targetText, ...recentMessages.slice(-8).map(m => m.content)].join('\n').normalize('NFKC').toLowerCase();
    const entries = [];
    for (const pack of packs) {
      for (const card of Array.isArray(pack.cards) ? pack.cards : []) {
        if (!card || card.enabled === false || card.mode === 'off' || (card.mode === 'manual' && card.manualSelected === false)) continue;
        const full = String(card.full ?? card.content ?? card.compact ?? card.summary ?? '').trim();
        if (!full && !card.exactQuote) continue;
        const terms = [card.title, ...(Array.isArray(card.aliases) ? card.aliases : []), ...(Array.isArray(card.triggers) ? card.triggers : []), ...(Array.isArray(card.entities) ? card.entities : [])]
          .map(value => String(value || '').normalize('NFKC').toLowerCase().trim()).filter(Boolean);
        const score = terms.reduce((n, term) => n + (pool.includes(term) ? Math.min(12, term.length + 2) : 0), 0) + (card.mode === 'always' ? 5 : 0);
        entries.push({ pack:pack.title || '자료팩', card, full, score });
      }
    }
    entries.sort((a,b) => b.score - a.score);
    const picked = entries.filter(row => row.score > 0).slice(0, 80);
    for (const row of entries) {
      if (picked.length >= 80) break;
      if (!picked.includes(row) && (row.card.mode === 'always' || row.card.mode === 'manual')) picked.push(row);
    }
    const rows = picked.map(({pack,card,full}) => [
      '[' + pack + '] [' + (card.type || '기타') + '] ' + (card.title || '제목 없음'),
      full,
      card.exactQuote ? '원문 대사: ' + card.exactQuote : '',
      Array.isArray(card.aliases) && card.aliases.length ? '별칭: ' + card.aliases.join(', ') : '',
    ].filter(Boolean).join('\n'));
    return clipText(rows.join('\n\n'), 90000, false) || '(관련 활성 자료 카드 없음)';
  }

  function renderManagerCognition(room) {
    const cards = (Array.isArray(room?.knowledgeCards) ? room.knowledgeCards : []).filter(card => card && !card.archived && card.fact);
    if (!cards.length) return '(인물·인지 데이터 없음)';
    const status = { knows:'알고 있음', 'does-not-know':'모름', suspects:'의심', mistaken:'오해', unconfirmed:'미확인' };
    const lines = room.personPlayerName ? ['플레이어: ' + room.personPlayerName] : [];
    for (const card of cards) {
      lines.push('- ' + (card.person || '인물 미지정') + ' · ' + (status[card.status] || '미확인') + ': ' + card.fact);
      if (card.status === 'mistaken' && card.actualFact) lines.push('  실제 사실: ' + card.actualFact);
      if (Array.isArray(card.hiddenFrom) && card.hiddenFrom.length) lines.push('  숨기는 대상: ' + card.hiddenFrom.join(', ') + (card.concealmentNote ? ' · ' + card.concealmentNote : ''));
      if (card.evidence) lines.push('  근거: ' + card.evidence);
    }
    return clipText(lines.join('\n'), 75000, false);
  }

  function renderManagerRelationships(room) {
    const rows = (Array.isArray(room?.personStateRecords) ? room.personStateRecords : []).filter(row => row && row.active !== false && row.type === 'relationship');
    if (!rows.length) return '(관계·감정선 데이터 없음)';
    return clipText(rows.map(row => [
      (row.person || '?') + ' → ' + (row.target || '?'),
      row.official ? '공식 관계: ' + row.official : '',
      row.stance ? '현재 태도: ' + row.stance : '',
      row.conflict ? '남은 쟁점: ' + row.conflict : '',
      row.trajectory ? '핵심 전환: ' + row.trajectory : '',
      row.evidence ? '근거: ' + row.evidence : '',
    ].filter(Boolean).join('\n')).join('\n\n'), 50000, false);
  }

  function renderManagerSpeech(room) {
    const rows = (Array.isArray(room?.personStateRecords) ? room.personStateRecords : []).filter(row => row && row.active !== false && row.type === 'speech');
    if (!rows.length) return '(호칭·말투 데이터 없음)';
    return clipText(rows.map(row => [
      (row.person || '?') + ' → ' + (row.target || '?') + ':',
      row.address ? '호칭=' + row.address : '',
      row.tone ? '말투=' + row.tone : '',
      row.context ? '조건=' + row.context : '',
      row.evidence ? '근거=' + row.evidence : '',
    ].filter(Boolean).join(' ')).join('\n'), 30000, false);
  }

  function renderSlots(room, group) {
    const rows = (Array.isArray(room?.slots) ? room.slots : []).filter(s => s?.group === group && s.enabled !== false && String(s.content || '').trim());
    if (!rows.length) return group === 'character' ? '(캐릭터 설정 없음)' : group === 'item' ? '(중요 물품 없음)' : '(기타/OOC 설정 없음)';
    return clipText(rows.map(s => `[${s.title || (group === 'character' ? '캐릭터' : group === 'item' ? '중요 물품' : '기타')}]\n${s.content}`).join('\n\n'), group === 'character' ? 65000 : 45000, false);
  }

  function uniqueReviewPacks(packs) {
    const seen=new Set();
    return packs.filter(pack=>{
      const identity=String(pack?.scopeId||pack?.id||'');
      if(!identity)return true;
      const key=identity+'\n'+JSON.stringify(pack);
      if(seen.has(key))return false;
      seen.add(key);return true;
    });
  }

  async function readWishCoreSnapshot(targetText, recentMessages, options={}) {
    const apiChatId = getChatId();
    const roomKey = getRoomScopeKey(apiChatId);
    const db = await openWishDb();

    // RP CORE는 선택적 증강자료다. DB 자체가 아직 없거나 현재 방 room이
    // 생성되기 전이어도 Recent Context 단독 검수는 계속 진행한다.
    if (!db) {
      return {
        room:null, cognition:null, activePacks:[], apiChatId, roomKey,
        available:false, reason:'RP CORE DB 없음'
      };
    }

    try {
      const hasRooms = db.objectStoreNames.contains('rooms');
      const storedRoom = hasRooms ? await idbGet(db, 'rooms', roomKey) : null;
      const liveRoom = WSUITE.host?.room?.();
      const room = WSUITE.host.refinerRoomView(liveRoom?.chatId === roomKey ? liveRoom : storedRoom);
      const cognition = db.objectStoreNames.contains('cognitionRooms')
        ? await idbGet(db, 'cognitionRooms', apiChatId)
        : null;

      let activePacks = [];
      if (room && db.objectStoreNames.contains('characterLibraries')) {
        const libraries = await idbGetAll(db, 'characterLibraries');
        const activeIds = new Set((Array.isArray(room.activeLorePackIds) ? room.activeLorePackIds : []).map(String));
        activePacks = libraries.filter(p => activeIds.has(String(p?.scopeId || '')));
      }

      const manager=await window.__WISH_RP_MANAGER_AI_BRIDGE__?.recallReference(targetText,recentMessages,roomKey,options);
      const combinedRoom=manager?.room?{...room,...manager.room}:room;
      activePacks=uniqueReviewPacks([...activePacks,...(Array.isArray(combinedRoom?.lorePacks)?combinedRoom.lorePacks:[]).filter(p=>p?.enabled!==false)]);
      return {
        longTermText:manager?.longTermText||'',longTermCount:manager?.longTermCount||0,
        room: combinedRoom || null,
        cognition: cognition || null,
        activePacks,
        apiChatId,
        roomKey,
        available: !!room,
        reason: room ? '' : (hasRooms ? '현재 방 RP CORE room 미생성' : 'RP CORE rooms 저장소 없음')
      };
    } finally {
      try { db.close(); } catch (_) {}
    }
  }

  function reviewTextBudgets(texts,total,maxPerText=Infinity) {
    const budgets=texts.map(()=>0);let remaining=total;
    let active=texts.map((text,index)=>({index,length:Math.min(maxPerText,String(text||'').length)}));
    while(active.length&&remaining>0){
      const share=Math.max(1,Math.floor(remaining/active.length)),next=[];
      for(const row of active){const take=Math.min(share,row.length-budgets[row.index],remaining);budgets[row.index]+=take;remaining-=take;if(budgets[row.index]<row.length)next.push(row);}
      active=next;
    }
    return budgets;
  }
  function compactReviewEvidence(sections,scene) {
    const protectedChars=String(sections.extras||'').length+String(sections.currentState||'').length;
    const keys=['actors','relationships','speech','characters','timeline','dateLogs','lore','longTerm'];
    const budget=Math.max(19200,(fastReview()?48000:64000)-protectedChars);
    const texts=keys.map(key=>sections[key]||'');
    if(texts.reduce((n,text)=>n+text.length,0)<=budget)return;
    // Distribute unused short-section space to other relevant sections. Saved memory is untouched.
    const budgets=reviewTextBudgets(texts,Math.max(0,budget-keys.length*140));
    keys.forEach((key,index)=>{sections[key]=selectEvidenceText(texts[index],scene,budgets[index])||'(관련 근거 미회수 · 사실 부재를 뜻하지 않음)';});
  }
  function buildWishCoreReference(snapshot,targetText,recentMessages){
    snapshot=snapshot||{room:null,activePacks:[],available:false,reason:'RP Manager 자료 없음'};
    const room=snapshot.room||{},scene=evidenceScene(targetText,recentMessages,room),topics=settings.reviewTopics||normalizeReviewTopics(null);
    const enabled=key=>topics[key]!==false,continuity=!structuralOnly();
    const current=(room.slots||[]).find(s=>s?.id==='currentState'),logs=(room.slots||[]).find(s=>s?.id==='logSummary');
    const canon=(room.userCanonMemos||[]).filter(m=>m?.enabled!==false&&String(m?.text||'').trim());
    const slots=group=>(room.slots||[]).filter(s=>s?.group===group&&s.enabled!==false&&String(s.content||'').trim());
    const sectionRows=(rows,format,budget=10000)=>selectEvidenceRows(rows,format,scene,budget)||'(현재 장면 관련 기록 미회수 · 해당 사실이 없음을 뜻하지 않음)';
    const sections={
      extras:[canon.length?'[USER_CANON_MEMO · 사용자 직접 정정/고정]\n'+selectEvidenceText(canon.map(m=>m.text).join('\n\n'),scene,18000):'',selectEvidenceText(slots('extra').map(s=>'['+(s.title||'기타/OOC')+']\n'+s.content).join('\n\n'),scene,16000)].filter(Boolean).join('\n\n')||'(사용자 직접 정정 / 고정 OOC 없음)',
      currentState:continuity?selectEvidenceText(current?.content||'',scene,16000,true)||'(현재상태 없음)':'(연속성 검사 OFF)',
      actors:continuity&&(enabled('cognition')||enabled('presence')||enabled('facts')||enabled('userProtection'))?sectionRows((room.knowledgeCards||[]).filter(c=>c&&!c.archived&&c.fact),c=>[
        (c.person||'인물 미지정')+' · '+({knows:'알고 있음','does-not-know':'모름',suspects:'의심',mistaken:'오해',unconfirmed:'미확인'}[c.status]||'미확인')+': '+c.fact,
        c.actualFact?'실제 사실: '+c.actualFact:'',c.hiddenFrom?.length?'숨기는 대상: '+c.hiddenFrom.join(', ')+' · '+(c.concealmentNote||''):'',...(c.concealments||[]).map(x=>`은폐 ${x.holder} → ${x.target}: ${x.scope||''} · 공개 설명 ${x.publicVersion||''}`),c.evidence?'근거: '+c.evidence:''
      ].filter(Boolean).join('\n'),14000):'(인물·인지 검사 참고자료 생략)',
      relationships:continuity&&(enabled('relationships')||enabled('character')||enabled('hooks'))?sectionRows((room.personStateRecords||[]).filter(r=>r&&r.active!==false&&r.type==='relationship'),r=>[(r.person||'?')+' → '+(r.target||'?'),r.official?'공식 관계: '+r.official:'',r.stance?'현재 태도: '+r.stance:'',r.conflict?'남은 쟁점: '+r.conflict:'',r.trajectory?'핵심 전환: '+r.trajectory:'',r.evidence?'근거: '+r.evidence:''].filter(Boolean).join('\n'),10000):'(관계 검사 참고자료 생략)',
      speech:continuity&&enabled('speech')?sectionRows((room.personStateRecords||[]).filter(r=>r&&r.active!==false&&r.type==='speech'),r=>[(r.person||'?')+' → '+(r.target||'?'),r.address?'호칭: '+r.address:'',r.tone?'말투: '+r.tone:'',r.context?'조건: '+r.context:'',r.evidence?'근거: '+r.evidence:''].filter(Boolean).join('\n'),7000):'(호칭·말투 검사 OFF)',
      characters:continuity?sectionRows(slots('character'),s=>'['+(s.title||'캐릭터')+']\n'+selectEvidenceText(s.content,scene,6500),14000):'(캐릭터 설정 조회 생략)',
      timeline:continuity?sectionRows((room.storyTimelineCards||[]).filter(c=>c&&c.inject!==false),c=>'['+(c.timelineLabel||'기본 시간선')+' · '+(c.dateStart||'날짜 미정')+'] '+(c.title||'')+'\n'+(c.content||''),8000):'(타임라인 조회 생략)',
      dateLogs:continuity?selectEvidenceText(logs?.content||'',scene,10000)||'(날짜로그 없음)':'(날짜로그 조회 생략)',
      lore:continuity?[
        sectionRows((snapshot.activePacks||[]).flatMap(p=>(p.cards||[]).filter(c=>c&&c.enabled!==false&&c.mode!=='off'&&(c.mode!=='manual'||c.manualSelected!==false)).map(c=>({...c,packTitle:p.title}))),c=>'['+(c.packTitle||'자료집')+'] ['+(c.type||'참고')+'] '+(c.title||'')+'\n'+String(c.full??c.content??c.compact??c.summary??'')+'\n검색 연결: '+[...(c.aliases||[]),...(c.triggers||[]),...(c.entities||[])].join(', ')+(c.exactQuote?'\n원문 대사: '+c.exactQuote:''),14000),sectionRows(slots('item'),s=>'[중요 물품 · '+(s.title||'물품')+']\n'+s.content,8000)
      ].join('\n\n'):'(자료집·물품 조회 생략)',
      longTerm:continuity?selectEvidenceText(snapshot.longTermText||'',scene,8000)||'(관련 장기기억 없음)':'(장기기억 조회 생략)',
    };
    if(room.personPlayerName)sections.actors='플레이어 / USER: '+room.personPlayerName+'\n'+sections.actors;
    if(continuity){
      const supplement=(key,text,budget)=>{const selected=selectEvidenceText(text,scene,budget);if(selected)sections[key]+='\n\n[Suite 참고자료]\n'+selected;};
      if(enabled('cognition')||enabled('presence')||enabled('facts'))supplement('actors',renderCognition(snapshot.cognition),10000);
      if(enabled('relationships')||enabled('character')||enabled('hooks'))supplement('relationships',renderRelationships(room),7000);
      if(enabled('speech'))supplement('speech',renderSpeech(room),6000);
      supplement('lore',renderSuiteLorePacks(snapshot.activePacks||[],targetText,recentMessages),12000);
      const timeline=String(room.activeLogTimeline||'기본 시간선');
      const cards=(room.wishSuite?.cards||[]).filter(c=>c&&c.mode!=='off'&&c.status!=='retired'&&!c.stale&&(!c.timeline||c.timeline===timeline));
      const relevant=WSUITE.core.select(cards,[targetText,...recentMessages.map(m=>m.content)].join('\n'),{timeline,userName:room.wishSuite?.settings?.userName||''}).rows.map(r=>r.card);
      const ordered=[...new Map([...cards.filter(c=>c.locked||c.mode==='always'),...relevant].map(c=>[c.id,c])).values()].slice(0,120);
      if(ordered.length)supplement('lore',ordered.map(c=>'['+(WSUITE.core.KINDS[c.kind]||c.kind)+'] '+(c.title||'')+'\n'+WSUITE.core.content(c)).join('\n\n'),15000);
    }
    compactReviewEvidence(sections,scene);
    const availability=snapshot.available?'Saved Manager data for this room. Omitted or unretrieved records do NOT establish nonexistence.':'Manager reference unavailable ('+(snapshot.reason||'not available')+'). Review only checks supported by Recent Context; never infer missing canon.';
    sections.core=['[Evidence Packet Availability]\n'+availability,'[USER_DIRECT_CORRECTION / FIXED_OOC]\n'+sections.extras,...[['Current State','currentState'],['Actors & Cognition','actors'],['Relationships','relationships'],['Speech / Address','speech'],['Character Settings','characters'],['Timeline','timeline'],['Date Logs','dateLogs'],['Lore / Items','lore'],['Long-term Memory','longTerm']].map(([label,key])=>'[RP Manager '+label+']\n'+sections[key])].join('\n\n');
    sections.stats={available:!!snapshot.available,reason:snapshot.reason||'',longTermCount:Number(snapshot.longTermCount)||0,activePacks:(snapshot.activePacks||[]).length,loreEntries:(snapshot.activePacks||[]).reduce((n,p)=>n+(p.cards||[]).filter(c=>c?.enabled!==false&&c?.mode!=='off').length,0),actors:scene.people.length,facts:(room.knowledgeCards||[]).filter(c=>!c?.archived).length,relationships:(room.personStateRecords||[]).filter(r=>r?.active!==false&&r?.type==='relationship').length,speech:(room.personStateRecords||[]).filter(r=>r?.active!==false&&r?.type==='speech').length};
    return sections;
  }

  function stripUserInjectedNotes(text){
    return String(text||'').replace(/<!--RP_CONTEXT_MANAGER_START[\s\S]*?RP_CONTEXT_MANAGER_END-->/g,'').replace(/<rp_context_manager\b[^>]*>[\s\S]*?<\/rp_context_manager>/gi,'').trim();
  }

  function buildContextText(messages, target) {
    const turns = Math.max(0, Math.min(truncationOnly()?2:12,Number(settings.contextTurns)||0));
    if (!turns) return '최근 대화 내역 없음.';
    let ctx = messages.slice();
    const targetIndex=target?ctx.findIndex(m=>String(m.id)===String(target.id)):-1;
    if(targetIndex>=0)ctx=ctx.slice(0,targetIndex);
    else if(target?.id)return '대상 응답 이전 대화를 조회 범위에서 찾지 못했습니다. 이후 대화는 근거로 사용하지 않습니다.';
    ctx = ctx.slice(-(2 * turns + 1));
    if (!ctx.length) return '최근 대화 내역 없음.';
    const texts=ctx.map(m=>stripUserInjectedNotes(m.content));
    const budgets=reviewTextBudgets(texts,truncationOnly()?12000:fastReview()?12000:24000,truncationOnly()?4500:fastReview()?6000:10000);
    return ctx.map((m,index)=>{
      const text=texts[index],budget=budgets[index];
      // 마지막 행동뿐 아니라 응답 첫머리의 완료된 상태 전환도 참고자료에 남깁니다.
      const head=Math.floor(budget*.35),tail=budget-head;
      const excerpt=text.length<=budget?text:text.slice(0,head)+`\n[중간 ${text.length-budget}자 생략; 회수되지 않은 사건은 확인 불가]\n`+text.slice(-tail);
      return `${m.role} [message ${m.id||index}]: ${excerpt}`;
    }).join('\n\n');
  }

  function fillPrompt(template, values) {
    let out = String(template || '');
    const replacements = {
      '{core}': values.core,
      '{currentState}': values.currentState,
      '{dateLogs}': values.dateLogs,
      '{characters}': values.characters,
      '{extras}': values.extras,
      '{lore}': values.lore,
      '{memory}': [values.currentState, values.dateLogs].join('\n\n'),
      '{actors}': values.actors,
      '{relationships}': values.relationships,
      '{speech}': values.speech,
      '{timeline}':values.timeline,
      '{longTerm}':values.longTerm,
      '{structuralHints}':values.structuralHints,
      '{formatReference}':values.formatReference,
      '{context}': values.context,
      '{message}': values.message,
      '{passWord}': 'PASS',
    };
    out=out.replace(/\{(?:core|currentState|dateLogs|characters|extras|lore|memory|actors|relationships|speech|timeline|longTerm|structuralHints|formatReference|context|message|passWord)\}/g,key=>String(replacements[key]??''));
    if(settings.template==='custom')out+='\n\n[ACTIVE_REVIEW_CONTRACT · overrides conflicting template instructions]\n'+(truncationOnly()?'Your ONLY job is to detect and repair clear output truncation. Do not change any other sentence.\n':'')+reviewCheckInstructions()+'\n'+REVIEW_OUTPUT_CONTRACT+'\nOnly the enabled categories can produce corrections. Disabled checks must not affect verdicts.\n';
    if(settings.template==='custom'&&!String(template).includes('{formatReference}')&&!truncationOnly())out+='\n[OUTPUT_FORMAT_REFERENCE]\n'+String(values.formatReference||'');
    return out + `\n\nTARGET BOUNDARY: [New Speech] is the only text you may correct. RP Manager references and [Recent Context] are reference data and are never correction targets. Never return, rewrite, or substitute a user message as refined_text. Every replacements.from MUST be an exact substring of [New Speech]. FORMAT PRESERVATION: for ordinary corrections, preserve the original paragraph boundaries, newline count, blank-line pattern, Markdown markers, and status-block layout of replacements.from. Change only the erroneous content. Do not reflow, prettify, or insert extra blank lines. Only a repair that inherently requires missing structure, such as a missing required INFO/HUD block, a missing bilingual line, or confirmed narration/dialogue marker damage, may restore only the minimum necessary lines or markers. If [New Speech] needs no change, return the appropriate JSON verdict; PASS only when no supported issue exists.`;
  }

  function parseGeminiText(json) {
    const candidates = Array.isArray(json?.candidates) ? json.candidates : [];
    for (const candidate of candidates) {
      const parts = candidate?.content?.parts;
      if (!Array.isArray(parts)) continue;
      const text = parts.filter(p => !p?.thought).map(p => typeof p?.text === 'string' ? p.text : '').join('');
      if (text) return text;
    }
    return '';
  }

  function fastReview(config=settings){return (activeReviewMode||config.reviewMode)!=='normal';}

  function selectedThinkingLevel(test = false) {
    // 연결 테스트는 reasoning 때문에 512 토큰을 다 써 빈 응답이 되는 일을 피하도록 low로 고정합니다.
    return test ? 'low' : normalizeThinkingLevel(settings.responseRefinerThinkingLevel);
  }

  function generationConfig(test = false) {
    // Gemini 3.8/3.7 공식 권고에 따라 temperature/topP/topK/candidateCount/thinkingBudget은 넣지 않습니다.
    return {
      maxOutputTokens: test ? 2048 : 32768,
      thinkingConfig: { thinkingLevel: selectedThinkingLevel(test) },
    };
  }

  function firebaseGenerationConfig(firebase, test = false) {
    const config = generationConfig(test);
    const level = selectedThinkingLevel(test);
    const enumValue = firebase?.ThinkingLevel?.[level.toUpperCase()];
    config.thinkingConfig.thinkingLevel = enumValue ?? level;
    return config;
  }

  async function callAiStudio(prompt, { test = false } = {}) {
    const key = getApiKey();
    if (!key) throw new Error('Gemini API Key가 없습니다.');
    const body = {
      safetySettings: SAFETY,
      contents: [{ role:'user', parts:[{ text:String(prompt || '') }] }],
      generationConfig: generationConfig(test),
    };
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${currentModelId()}:generateContent`;
    let lastError = '';
    let lastErrorDetails = '';
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const res = await gmRequest(url, {
          method:'POST',
          headers:{ 'Content-Type':'application/json', 'x-goog-api-key':key },
          body:JSON.stringify(body),
          timeout:test ? 60000 : 120000,
        });
        let json = null;
        try { json = JSON.parse(res.responseText || ''); } catch (_) {}
        if (res.status >= 200 && res.status < 300) {
          const text = parseGeminiText(json);
          if (text) return { text, json, provider:'ai-studio' };
          lastError = `AI 응답이 비어 있음${json?.candidates?.[0]?.finishReason ? ` (${json.candidates[0].finishReason})` : ''}`;
          lastErrorDetails = JSON.stringify(json || {}, null, 2) || lastError;
        } else {
          const full = String(res.responseText || '');
          lastError = `Gemini HTTP ${res.status}: ${full.slice(0, 280)}`;
          lastErrorDetails = `Gemini HTTP ${res.status}\n${full || '(응답 본문 없음)'}`;
          if ([400,401,403,404].includes(res.status)) break;
        }
      } catch (e) {
        lastError = e.message || String(e);
        lastErrorDetails = formatErrorDetails(e);
      }
      if (attempt === 0) await sleep(1200);
    }
    const error = new Error(lastError || 'Gemini API 호출 실패');
    error.fullDetails = lastErrorDetails || lastError || 'Gemini API 호출 실패';
    throw error;
  }

  function parseFirebaseConfigInput(input) {
    const raw = String(input || '').trim();
    if (!raw) return null;
    let source = raw.replace(/^\s*(?:const|let|var)\s+firebaseConfig\s*=\s*/i, '').replace(/;\s*$/g, '').trim();
    const objectMatch = source.match(/\{[\s\S]*\}/);
    if (objectMatch) source = objectMatch[0];
    try {
      const parsed = JSON.parse(source);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
    } catch (_) {}
    const fields = ['apiKey','authDomain','databaseURL','projectId','storageBucket','messagingSenderId','appId','measurementId'];
    const parsed = {};
    for (const field of fields) {
      const escaped = field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const pattern = new RegExp(String.raw`(?:^|[,\{\s])(?:["']?${escaped}["']?)\s*:\s*(["'])((?:\\.|(?!\1)[\s\S])*?)\1`);
      const match = source.match(pattern);
      if (!match) continue;
      let v = match[2].replace(/\\n/g,'\n').replace(/\\r/g,'\r').replace(/\\t/g,'\t').replace(/\\\\/g,'\\');
      v = match[1] === '"' ? v.replace(/\\"/g,'"') : v.replace(/\\'/g,"'");
      parsed[field] = v;
    }
    if (Object.keys(parsed).length) return parsed;
    throw new Error('Firebase Config를 읽지 못했습니다. const firebaseConfig = { ... } 전체를 붙여 넣어 주세요.');
  }

  let firebaseModulePromise = null;
  async function loadFirebaseAiModules() {
    if (firebaseModulePromise) return firebaseModulePromise;
    firebaseModulePromise = (async () => {
      try {
        const [appModule, aiModule] = await Promise.all([
          import(`https://www.gstatic.com/firebasejs/${FIREBASE_SDK_VERSION}/firebase-app.js`),
          import(`https://www.gstatic.com/firebasejs/${FIREBASE_SDK_VERSION}/firebase-ai.js`),
        ]);
        if (!appModule?.initializeApp || !aiModule?.getAI || !aiModule?.getGenerativeModel || !aiModule?.AgentPlatformBackend) {
          throw new Error('필수 Firebase AI Agent Platform 모듈을 찾지 못했습니다.');
        }
        return { ...appModule, ...aiModule };
      } catch (e) {
        firebaseModulePromise = null;
        throw new Error(`Firebase SDK ${FIREBASE_SDK_VERSION} 로드 실패: ${e.message || e}`);
      }
    })();
    return firebaseModulePromise;
  }

  async function callFirebase(prompt, { test = false } = {}) {
    const firebaseConfig = parseFirebaseConfigInput(getFirebaseConfig());
    if (!firebaseConfig) throw new Error('Firebase Config가 비어 있습니다.');
    const firebase = await loadFirebaseAiModules();
    const identity = JSON.stringify({ projectId:firebaseConfig.projectId || '', appId:firebaseConfig.appId || '' });
    const name = `crr-rpcore-${simpleHash(identity)}`+CFA.suffix(firebaseConfig);
    const app = firebase.getApps().some(x => x.name === name) ? firebase.getApp(name) : firebase.initializeApp(firebaseConfig, name);
    await CFA.prepare(app,FIREBASE_SDK_VERSION);
    const ai = firebase.getAI(app, { backend:new firebase.AgentPlatformBackend(FIREBASE_LOCATION) });
    const gm = firebase.getGenerativeModel(ai, { model:currentModelId(), generationConfig:firebaseGenerationConfig(firebase, test) });
    try {
      const result = await gm.generateContent({ contents:[{ role:'user', parts:[{ text:String(prompt || '') }] }] });
      const response = result?.response;
      const finishReason = String(response?.candidates?.[0]?.finishReason || '');
      if (/MAX_TOKENS|LENGTH|BUDGET_EXCEEDED/i.test(finishReason)) throw new Error(`출력이 토큰 한도에서 잘렸습니다. (${finishReason})`);
      const text = String(await response?.text?.() || '').trim();
      if (!text) throw new Error(`빈 응답${finishReason ? ` (${finishReason})` : ''}`);
      return { text, json:result, provider:'firebase' };
    } catch (e) {
      const error = new Error(`Firebase AI Logic 호출 실패: ${e.message || e}`);
      error.fullDetails = `Firebase AI Logic 호출 실패\n${formatErrorDetails(e)}`;
      throw error;
    }
  }

  function reviewOutputTokenBudget(options={},target=activeReviewTarget,config=settings){
    if(options.test)return 2048;
    const level=normalizeThinkingLevel(config.responseRefinerThinkingLevel);
    const reserve=level==='high'?32768:level==='medium'?24576:16384;
    const textAllowance=Math.ceil(String(target?.content||'').length*1.5)+4096;
    const requested=Number(options.maxOutputTokens)||0;
    return Math.min(32768,Math.max(reserve,textAllowance,requested));
  }
  function reviewOutputLimitError(response,options={}){
    const budget=reviewOutputTokenBudget(options);
    const error=new Error('AI 검토 결과가 출력 한도에 도달해 교정을 완료하지 못했습니다. 원본 RP 응답은 정상적으로 유지했습니다. 다시 검수하면 최대 출력 예산으로 검토합니다. 반복되면 응답교정 추론 수준을 Low로 낮춰 주세요.');
    error.code='REVIEW_OUTPUT_LIMIT';
    error.fullDetails=JSON.stringify({code:error.code,finishReason:String(response?.finishReason||''),maxOutputTokens:budget,thinkingLevel:selectedThinkingLevel(),model:currentModelId(),usage:response?.usage||null},null,2);
    return error;
  }

  async function callModel(prompt, options = {}) {
    const showProgress=!options.test&&!!activeReviewTarget;
    if(showProgress){
      reviewRequestStartedAt=Date.now();
      clearInterval(reviewProgressTimer);
      reviewProgressTimer=setInterval(()=>{
        if(!badge||badge.style.display==='none'||badge.dataset.result||!workerBusy)return;
        const seconds=Math.floor((Date.now()-reviewRequestStartedAt)/1000);
        badge.querySelector('[data-review-detail]').textContent=`${seconds>=45?'검토가 길어지고 있어요':'AI가 선택한 검사 항목을 확인하고 있어요'} · ${seconds}초`;
        positionReviewBadge();
      },1000);
    }
    try {
      if(!window.__WISH_RP_MANAGER_AI_BRIDGE__)throw new Error('RP Manager AI 연결을 확인할 수 없습니다.');
      return await window.__WISH_RP_MANAGER_AI_BRIDGE__.call(prompt, {...options,responseRefiner:true,model:currentModelId(),thinkingLevel:selectedThinkingLevel(!!options.test),responseJsonSchema:options.test?undefined:reviewResponseSchema(),maxOutputTokens:reviewOutputTokenBudget(options),reviewTimeoutMs:180000});
    } catch (e) {
      // 호출 오류가 나더라도 연결 상태를 자동 종료하지 않습니다.
      throw e;
    } finally {
      if(showProgress){clearInterval(reviewProgressTimer);reviewProgressTimer=0;}
    }
  }

  function parseJsonLoose(text) {
    if (!text) return null;
    const t = String(text).trim();
    const tries = [
      t,
      t.replace(/^```(?:json|javascript|js)?\s*/i, '').replace(/\s*```\s*$/i, '').trim(),
    ];
    for (const s of tries) {
      try { return JSON.parse(s); } catch (_) {}
    }
    const start = t.search(/[\[{]/);
    if (start < 0) return null;
    for (let end = t.length; end > start; end--) {
      const tail = t[end - 1];
      if (tail !== '}' && tail !== ']') continue;
      try { return JSON.parse(t.slice(start, end)); } catch (_) {}
    }
    return null;
  }

  function correctionUnits(original,parsed) {
    const replacements=Array.isArray(parsed?.replacements)?parsed.replacements:[];
    if(!replacements.length)return typeof parsed?.refined_text==='string'?[{from:original,to:parsed.refined_text,start:0,end:original.length,reason:parsed.reason||'전체 응답 수정',evidence:parsed.evidence||'전체 교정본을 직접 확인해 주세요.',verdict:parsed.verdict,category:'legacy',severity:'unconfirmed',autoApplyEligible:false}]:[];
    const units=replacements.map(r=>{
      const from=String(r?.from??''),start=original.indexOf(from);
      if(!from||start<0||original.indexOf(from,start+1)>=0)throw new Error('교정 대상 원문이 없거나 여러 위치에 있어 정확한 변경 범위를 확인할 수 없습니다.');
      return {...r,from,to:String(r?.to??''),start,end:start+from.length};
    }).sort((a,b)=>a.start-b.start);
    if(units.some((unit,i)=>i&&unit.start<units[i-1].end))throw new Error('교정 대상 범위가 서로 겹칩니다. 최신 응답을 다시 검수해 주세요.');
    return units;
  }
  function applyCorrectionUnits(original,units) {
    let result=original;
    for(const unit of [...units].sort((a,b)=>b.start-a.start))result=result.slice(0,unit.start)+unit.to+result.slice(unit.end);
    return result;
  }
  function applyReplacements(original, parsed) {return applyCorrectionUnits(original,correctionUnits(original,parsed));}

  function looksLikeUserCopy(candidate, recentMessages) {
    const c = normalizeText(candidate);
    if (c.length < 8) return false;
    return recentMessages.some(m => {
      if (m.role !== 'user') return false;
      const u = normalizeText(m.content);
      if (!u) return false;
      if (c === u) return true;
      const ratio = Math.min(c.length, u.length) / Math.max(c.length, u.length);
      return ratio >= 0.92 && (c.includes(u) || u.includes(c));
    });
  }

  async function patchMessage(target,newText){assertScope(target.suiteScope);return WSUITE.host.refinerPatch({...target,reviewScope:target.suiteScope,refinerHistorical:target.refinerHistorical===true},newText,()=>assertScope(target.suiteScope));}

  function escapeHTML(value) {
    return String(value ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function stripMarkdown(text) {
    return String(text || '')
      .replace(/`{3}\w*\n?/g, '')
      .replace(/`([^`]+)`/g, '$1')
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/\*([^*]+)\*/g, '$1')
      .replace(/~~(.+?)~~/g, '$1')
      .replace(/^#+\s+/gm, '')
      .replace(/^[-*+]\s+/gm, '')
      .replace(/^\d+\.\s+/gm, '')
      .replace(/^>\s+/gm, '')
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      .replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1')
      .replace(/\n{2,}/g, '\n')
      .trim();
  }

  function normalizeCrackLinebreaks(value) {
    return String(value ?? '')
      .replace(/\r\n?/g, '\n')
      .replace(/\u0000/g, '');
  }

  const RENDER_BOUNDARY = '\uE000';

  function logicalBreakBetweenTextNodes(a, b, root) {
    if (!(a instanceof Text) || !(b instanceof Text)) return true;
    const BLOCK_TAGS = new Set(['P','DIV','LI','BLOCKQUOTE','PRE','H1','H2','H3','H4','H5','H6','TABLE','TR','TD','TH','SECTION','ARTICLE']);

    const nearestBlock = node => {
      let cur = node?.parentElement || null;
      while (cur && cur !== root) {
        if (BLOCK_TAGS.has(cur.tagName)) return cur;
        cur = cur.parentElement;
      }
      return root;
    };

    if (nearestBlock(a) !== nearestBlock(b)) return true;

    try {
      const range = document.createRange();
      range.setStartAfter(a);
      range.setEndBefore(b);
      const frag = range.cloneContents();
      if (frag.querySelector?.('br,p,div,li,blockquote,pre,h1,h2,h3,h4,h5,h6,table,tr,td,th,section,article')) return true;
    } catch (_) {}

    return false;
  }

  function buildRenderedTextIndex(root) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const segments = [];
    let flat = '';
    let prev = null;

    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      const raw = String(node.nodeValue || '');
      if (prev && logicalBreakBetweenTextNodes(prev, node, root)) flat += RENDER_BOUNDARY;
      const start = flat.length;
      flat += raw;
      segments.push({ node, start, end:flat.length });
      prev = node;
    }
    return { flat, segments };
  }

  function findUniqueRenderedRange(root, source) {
    const needle = normalizeCrackLinebreaks(source);
    if (!needle || needle.includes('\n') || needle.includes(RENDER_BOUNDARY)) return null;

    const index = buildRenderedTextIndex(root);
    const at = index.flat.indexOf(needle);
    if (at < 0) return null;
    if (index.flat.indexOf(needle, at + 1) >= 0) return null;

    const end = at + needle.length;
    const overlaps = index.segments.filter(seg => seg.end > at && seg.start < end);
    if (!overlaps.length) return null;

    // 논리적 문단/줄바꿈 경계를 가로질러서는 절대 즉시 패치하지 않습니다.
    if (index.flat.slice(at, end).includes(RENDER_BOUNDARY)) return null;

    return { index, at, end, overlaps };
  }

  function replacePlainTextAcrossNodes(root, from, to) {
    const source = normalizeCrackLinebreaks(from);
    const replacement = normalizeCrackLinebreaks(to);
    if (!source || source.includes('\n') || replacement.includes('\n')) return false;

    const match = findUniqueRenderedRange(root, source);
    if (!match) return false;

    const { at, end, overlaps } = match;
    let remaining = replacement;

    overlaps.forEach((seg, i) => {
      const node = seg.node;
      const raw = String(node.nodeValue || '');
      const localStart = Math.max(0, at - seg.start);
      const localEnd = Math.min(raw.length, end - seg.start);
      const matchedLen = Math.max(0, localEnd - localStart);

      let piece = '';
      if (i === overlaps.length - 1) {
        piece = remaining;
        remaining = '';
      } else {
        const take = Math.min(matchedLen, remaining.length);
        piece = remaining.slice(0, take);
        remaining = remaining.slice(take);
      }

      node.nodeValue = raw.slice(0, localStart) + piece + raw.slice(localEnd);
    });

    return remaining.length === 0;
  }

  function domStructureSignature(root) {
    const out = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      if (node.nodeType === Node.TEXT_NODE) out.push('#text');
      else out.push(`<${node.nodeName}>`);
    }
    return out.join('|');
  }

  function simulateSafeRenderedReplacements(root, replacements) {
    if (!(root instanceof Element)) return false;
    const clone = root.cloneNode(true);
    const beforeSig = domStructureSignature(clone);

    for (const rep of replacements) {
      const fromPlain = stripMarkdown(String(rep?.from ?? ''));
      const toPlain = stripMarkdown(String(rep?.to ?? ''));
      if (!fromPlain || fromPlain.includes('\n') || toPlain.includes('\n')) return false;
      if (!replacePlainTextAcrossNodes(clone, fromPlain, toPlain)) return false;
    }

    return domStructureSignature(clone) === beforeSig;
  }

  function singlePlainDiff(oldText, newText) {
    const a = normalizeCrackLinebreaks(oldText);
    const b = normalizeCrackLinebreaks(newText);
    let start = 0;
    while (start < a.length && start < b.length && a[start] === b[start]) start++;
    let aEnd = a.length;
    let bEnd = b.length;
    while (aEnd > start && bEnd > start && a[aEnd - 1] === b[bEnd - 1]) {
      aEnd--;
      bEnd--;
    }
    return { from:a.slice(start, aEnd), to:b.slice(start, bEnd) };
  }

  function findVisibleMessageMarkdown(target) {
    const id = String(target?.id || '');
    if (id) {
      try {
        const escaped = CSS.escape(id);
        const host = document.querySelector(
          `[data-message-id="${escaped}"],[data-message-group-id="${escaped}"]`
        );
        const exact = host?.matches?.('.wrtn-markdown') ? host : host?.querySelector?.('.wrtn-markdown');
        if (exact) return exact;
      } catch (_) {}
    }

    const oldPlain = stripMarkdown(target?.content || '');
    const snippet = normalizeText(oldPlain.length > 48 ? oldPlain.slice(-48) : oldPlain);
    if (!snippet) return null;
    for (const node of document.querySelectorAll('.wrtn-markdown')) {
      if (normalizeText(node.textContent).includes(snippet)) return node;
    }
    return null;
  }

  /*
   * 서버 원문은 PATCH로 수정하되, 화면의 .wrtn-markdown 전체를 innerHTML로 다시 만들지 않습니다.
   * Crack의 기존 DOM 구조(문단/줄바꿈/서식)는 그대로 두고 안전하게 찾을 수 있는 텍스트 조각만
   * Text node 수준에서 바꿉니다. 이렇게 하면 <p> 경계가 개행으로 재직렬화되어
   * 한 줄씩 빈 줄이 끼는 현상을 피할 수 있습니다.
   *
   * 첨부된 "수정창 줄바꿈 보존" 확프와 같은 원칙으로, 줄바꿈은 paragraph 재생성이 아니라
   * 필요한 경우에만 <br>로 표현합니다. 안전한 위치를 찾지 못하면 DOM을 억지로 재구성하지 않고
   * 서버 반영만 유지하여 Crack의 네이티브 렌더가 형식을 결정하도록 둡니다.
   */
  function patchVisibleMessage(target, newText, parsed = null) {
    const node = findVisibleMessageMarkdown(target);
    if (!node) return false;

    const reps = Array.isArray(parsed?.replacements) ? parsed.replacements : [];
    if (reps.length) {
      // 실제 DOM을 만지기 전에 복제본에서 전체 교체를 먼저 시뮬레이션합니다.
      // 모든 교체가 유일하게 식별되고 DOM 구조가 그대로일 때만 실화면에 적용합니다.
      if(reps.some(rep=>String(rep.from)!==String(rep.to)&&stripMarkdown(rep.from)===stripMarkdown(rep.to)))return false;
      if (!simulateSafeRenderedReplacements(node, reps)) return false;

      // 실화면 적용 중 예상치 못한 DOM 변화가 끼어들어도 부분 적용 상태를 남기지 않습니다.
      // Text node 값만 스냅샷하고 실패 시 그대로 되돌리므로 DOM 구조/이벤트는 건드리지 않습니다.
      const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
      const snapshot = [];
      for (let t = walker.nextNode(); t; t = walker.nextNode()) snapshot.push([t, String(t.nodeValue || '')]);

      for (const rep of reps) {
        const fromPlain = stripMarkdown(String(rep?.from ?? ''));
        const toPlain = stripMarkdown(String(rep?.to ?? ''));
        if (!replacePlainTextAcrossNodes(node, fromPlain, toPlain)) {
          for (const [t, value] of snapshot) {
            try { if (t?.isConnected) t.nodeValue = value; } catch (_) {}
          }
          return false;
        }
      }
      return true;
    }

    // 사용자가 확인창에서 교정본을 직접 수정했거나 replacements가 없는 경우에도
    // 단일 차이가 한 문단 안에서 유일하게 식별되는 경우만 복제본 검증 후 즉시 반영합니다.
    const oldPlain = stripMarkdown(target?.content || '');
    const newPlain = stripMarkdown(newText);
    const diff = singlePlainDiff(oldPlain, newPlain);
    if (!diff.from || diff.from.includes('\n') || diff.to.includes('\n')) return false;

    const synthetic = [{ from:diff.from, to:diff.to }];
    if (!simulateSafeRenderedReplacements(node, synthetic)) return false;

    const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
    const snapshot = [];
    for (let t = walker.nextNode(); t; t = walker.nextNode()) snapshot.push([t, String(t.nodeValue || '')]);
    if (replacePlainTextAcrossNodes(node, diff.from, diff.to)) return true;
    for (const [t, value] of snapshot) {
      try { if (t?.isConnected) t.nodeValue = value; } catch (_) {}
    }
    return false;
  }

  async function applyCorrection(target, correctedText, reason, parsed = null, options = {}) {
    assertScope(target.suiteScope);
    setStatus('서버 반영 중');
    const recent=await fetchRecentMessages(20);
    if(looksLikeUserCopy(correctedText,recent))throw new Error('사용자 입력과 같은 교정본은 적용할 수 없습니다.');
    const safeText = normalizeCrackLinebreaks(correctedText);
    saveCorrectionArchive(target,safeText,reason,'적용 대기');
    let result;
    try{result=await patchMessage(target,safeText);}catch(error){saveCorrectionArchive(target,safeText,reason+' · '+String(error.message||error),'적용 확인 실패');throw error;}
    if(!scopeIsCurrent(target.suiteScope)){saveCorrectionArchive(target,safeText,reason,'서버 저장 확인 · 화면 이동됨');return {...target,id:result.id,content:result.content};}
    baselineFingerprint = messageFingerprint(result);
    markProcessed({ id: result.id, content: result.content });
    if (result.pendingSaveError) { window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue('error','응답 교정은 저장됐지만 주입 복구 정보의 로컬 저장을 확인해 주세요: '+result.pendingSaveError,target.id); toast('교정 저장 완료 · 로컬 주입 정보 확인 필요','error'); }
    const domNode=findVisibleMessageMarkdown(target);
    let domOk=patchVisibleMessage(target,result.content,parsed);
    if(domOk&&domNode){const expected=domNode.textContent;await sleep(180);domOk=domNode.isConnected&&domNode.textContent===expected;}
    saveCorrectionArchive(target,safeText,reason,domOk?'서버 저장·화면 반영 확인':'서버 저장 확인 · 화면 새로고침 필요');
    try{await window.__WISH_RP_MANAGER_AI_BRIDGE__?.sourceMutated(target.id,messageFingerprint(target),messageFingerprint({id:result.id,content:result.content}),getRoomScopeKey(getChatId()));}catch(error){window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue('error','교정은 서버에 저장됐지만 관련 초안 상태 저장에 실패했습니다. 원문을 다시 검증해 주세요.',target.id);toast('교정 저장 완료 · 관련 초안 상태 확인 필요','error');}
    addProcessHistory('교정 적용',reason,{target,corrected:{id:result.id,content:result.content},verdict:parsed?.verdict||''});
    setStatus(options.reloadAfter === false ? (domOk?'교정 완료':'서버 저장 완료 · 화면 갱신 필요') : '교정 완료 · 새로고침 준비', 'ok');
    if (options.reloadAfter === false) showReviewNotice(domOk?'교정 완료':'교정 저장 완료 · 화면 갱신 필요', domOk ? String(reason||'응답의 오류를 수정했습니다.') : '서버 저장은 확인됐지만 화면 갱신은 확인하지 못했습니다. 남은 교정 확인이 끝나면 자동으로 새로고침합니다.', 'ok', domOk ? 3400 : 5000);
    else scheduleRefinerReload(domOk ? 650 : 350);
    return {...target,id:result.id,content:result.content};
  }

  function refinerGenerationVisible() {
    const candidates=document.querySelectorAll('[data-state="streaming"],[data-status="generating"],[aria-label="생성 중"],[aria-label="응답 생성 중"],button[aria-label*="생성 중지"],button[aria-label*="응답 중지"]');
    return [...candidates].some(node=>{
      if(node.closest('[id^="rpcm-"],.rr-settings-sheet,.rr-confirm-box'))return false;
      const style=getComputedStyle(node);
      return style.display!=='none'&&style.visibility!=='hidden'&&node.getClientRects().length>0;
    });
  }
  async function waitStableAssistant() {
    let previous=null,stableSamples=0;
    const roomId=getChatId();
    for(let i=0;i<8;i++){
      if(getChatId()!==roomId)return null;
      const current=await findLastAssistant();
      const pending=/^(streaming|generating|pending|in_progress)$/i.test(String(current?.raw?.status||''));
      if(!current||pending||refinerGenerationVisible()){previous=null;stableSamples=0;}
      else {
        stableSamples=previous&&messageFingerprint(previous)===messageFingerprint(current)?stableSamples+1:0;
        previous=current;
        if(stableSamples>=3){
          // Rendered Markdown removes images, fences and HUD markup. Its plain text
          // is not an exact serialization of the server response, so equality is not
          // a completion test. Require stable server reads and no visible stop control.
          const final=await findLastAssistant();
          if(getChatId()!==roomId||!final||messageFingerprint(final)!==messageFingerprint(current)||refinerGenerationVisible())return null;
          if(/^(streaming|generating|pending|in_progress)$/i.test(String(final.raw?.status||'')))return null;
          if(findVisibleMessageMarkdown(final)||/^(completed|complete|done|success)$/i.test(String(final.raw?.status||''))||stableSamples>=5)return final;
        }
      }
      if(i<7)await sleep(1000);
    }
    return null;
  }

  function refinerTransportFailure(error) {
    const code=String(error?.code||'');
    // Application/readback/site-auth failures and unresolved correction proposals
    // remain blocked. Only a failed optional AI transport is eligible.
    if(/CRACK_AUTH|RESPONSE_READBACK|STALE|WISH_USER_ABORT|ABORTED|REVIEW_OUTPUT|SCHEMA|VALIDATION/i.test(code))return false;
    if(/^(?:AI_COOLDOWN|AI_QUEUE_FULL|AI_TIMEOUT|AI_NETWORK|AI_RATE_LIMIT)$/.test(code))return true;
    const status=Number(error?.status||error?.diagnostic?.httpStatus||error?.diagnostic?.status||error?.response?.status||0);
    const message=String(error?.message||'');
    return status===429||status>=500&&status<=599||/Failed to fetch|NetworkError|network error|fetch-error|Resource exhausted|Too Many Requests|\b429\b|AI.{0,20}(?:시간 초과|응답 제한)|요청 시간 초과/i.test(message);
  }

  async function runRefiner({ force = false, targetOverride = null, maxOutputTokens = 0, reviewMode = '' } = {}) {
    if (workerBusy) {
      if (force) toast('이미 교정 작업이 진행 중이야.');
      return;
    }
    if (!force && !settings.enabled) return;
    if(!enabledReviewTopics().length){setStatus('검사 항목 OFF');if(force)showReviewNotice('응답을 유지했어요','검사 항목이 모두 꺼져 있습니다. 검사할 항목을 선택해 주세요.','info',5000);return;}
    if (!connectionOk) {
      if(!force){const target=targetOverride||await findLastAssistant();if(target){setReviewGate(target,'error');showReviewFailure(target,new Error('공용 AI 연결 확인이 필요합니다.'));}}
      if (force) { openSettings();showReviewNotice('아직 검토하지 못했어요','AI 연결이 종료되어 있습니다. 설정에서 현재 연결 방식 테스트를 눌러 주세요.','error',6000); }
      return;
    }
    if (!providerReady()) {
      const target=targetOverride||await findLastAssistant();
      if(target){setReviewGate(target,'error');showReviewFailure(target,new Error('기존 공용 AI 연결 설정을 확인해 주세요.'));}
      if(force)showReviewNotice('아직 검토하지 못했어요','RP Manager의 공용 AI 연결 설정을 확인해 주세요.','error',6000);
      return;
    }
    const requestScope=captureScope();
    const chatId = getChatId();
    if (!chatId) { if (force) toast('채팅방 ID 감지 실패', 'error'); return; }

    workerBusy = true;activeReviewMode=reviewMode||settings.reviewMode;
    let aiTransportPending=false,priorReviewGate=null;
    try {
      setStatus('응답 완료 기다리는 중');
      const target = targetOverride ? normalizeMessage(targetOverride) : await waitStableAssistant();
      if (!target) {setStatus('응답 완료 확인 대기');if(force)showReviewNotice('아직 검토하지 못했어요','응답 완료를 아직 확인하지 못했습니다. 잠시 후 다시 검수해 주세요.','info',5000);return;}
      assertScope(requestScope);target.suiteScope=requestScope;
      if(isPendingResponse(target))throw new Error('선택한 응답이 아직 생성 중입니다. 완료된 뒤 다시 검수해 주세요.');
      if(targetOverride)await assertReviewSource(target,chatId);
      if (target.contextMalformed) throw new Error('숨김 주입 블록이 완전하지 않습니다. 주입 재검증 후 다시 검수해 주세요.');
      if (!target.content.trim()) throw new Error('검수할 응답 본문이 없습니다.');
      if (!force && isProcessed(target)) return;

      if(!enabledReviewTopics().length){markProcessed(target);setStatus('검사 항목 OFF');if(force)showReviewNotice('응답을 유지했어요','검사 항목이 모두 꺼져 있습니다. 검사할 항목을 선택해 주세요.','info',5000);return;}
      priorReviewGate=reviewGateRows()[String(target.id)]||null;
      target.reviewScope=chatStateKey();activeReviewTarget=target;activeReviewStartedAt=Date.now();setReviewGate(target,'review-running');
      if(!force){
        const autoKey=messageAutoKey(target);
        if(autoFailureKey&&autoFailureKey!==autoKey){autoFailureKey='';autoFailureCount=0;}
        lastAutoAssistantKey=autoKey;
      }
      setStatus('관련 기억 찾는 중');
      const latest=targetOverride?await findLastAssistant():target;
      const historical=!!latest&&String(latest.id)!==String(target.id);
      target.refinerHistorical=historical;
      const recent = await fetchRecentMessages(historical?50:truncationOnly()?Math.min(8,Math.max(4,2*Math.min(2,settings.contextTurns)+2)):Math.max(12,2*settings.contextTurns+8));
      let snapshot;
      try {
        snapshot = historical?{room:null,activePacks:[],available:false,reason:'과거 응답 검수 · 대상 이전 대화만 사용; 이후의 저장 상태를 소급 적용하지 않음'}:truncationOnly()?{room:null,activePacks:[],available:false,reason:'문장 끊김 전용 검사 · 기억 조회 생략'}:await readWishCoreSnapshot(target.content,recent,{includeLongTerm:!structuralOnly()});
      } catch (coreError) {
        console.warn('[Wish Response Refiner] RP Manager optional read failed; falling back to Recent Context only.', coreError);
        snapshot = {
          room:null, activePacks:[],
          apiChatId:chatId, roomKey:getRoomScopeKey(chatId), available:false,
          reason:`RP Manager 읽기 실패: ${coreError?.message || coreError}`
        };
      }
      const core = buildWishCoreReference(snapshot, target.content, recent);
      const contextText = buildContextText(recent, target);
      const formatAnalysis=outputFormatAnalysis(recent,target);

      setStatus('검수 중');
      const template = settings.template === 'custom' ? String(settings.customPrompt || '').trim() : currentBasicPrompt();
      if (!template) throw new Error('커스텀지침이 비어 있습니다.');
      const prompt = fillPrompt(template, {
        ...core,
        context: contextText,
        message: target.content,
        structuralHints:structuralHintsText(target.content),
        formatReference:buildOutputFormatReference(recent,target),
      });
      setStatus('응답 받아오는 중');
      const policy=(settings.exceptions||[]).filter(row=>row.enabled!==false).map(row=>row.text).join('\n');
      assertScope(requestScope);
      aiTransportPending=true;
      const response = await callModel(prompt+(policy?'\n[USER_APPROVED_REVIEW_POLICY]\n'+policy+'\n[/USER_APPROVED_REVIEW_POLICY]':''),{maxOutputTokens,shouldRun:()=>scopeIsCurrent(requestScope)});
      aiTransportPending=false;
      if(/MAX_TOKENS|LENGTH|BUDGET_EXCEEDED|TOKEN_LIMIT|INCOMPLETE/i.test(String(response.finishReason||'')))throw reviewOutputLimitError(response,{maxOutputTokens});
      await assertReviewSource(target,chatId);
      setStatus('교정 결과 확인 중');
      const text = String(response.text || '').trim();

      let parsed=/^PASS\s*$/i.test(text)?{verdict:'PASS',reason:'',replacements:[]}:normalizeReviewResult(parseJsonLoose(text));
      if (!parsed) throw new Error(`응답 해석 실패: ${text.slice(0, 120)}`);
      if(parsed.verdict==='PASS'&&formatAnalysis.missing.length){
        parsed={verdict:'AMBIGUOUS',replacements:[],reason:`최근 ${formatAnalysis.history.length}개 AI 응답에서 반복된 ${formatAnalysis.missing.join(' / ')} 블록이 이번 응답에 없거나 코드블록 형식이 깨졌습니다. AI가 복구 내용을 확정하지 못해 원본을 유지했습니다.`,evidence:'최근 완료 AI 응답의 필수 블록 구조와 비교한 누락 후보'};
      }
      const verdict=String(parsed.verdict||'').toUpperCase();
      if(verdict==='MEMORY_STALE'||verdict==='AMBIGUOUS'){
        markProcessed(target);baselineFingerprint=messageFingerprint(target);
        const reason=String(parsed.reason||parsed.evidence||'최신 RP와 저장 기억의 관계를 확인해 주세요.');
        addProcessHistory(verdict==='MEMORY_STALE'?'기억 검토 필요':'근거 불충분',reason,{target,verdict});
        setStatus(verdict==='MEMORY_STALE'?'기억 검토 필요':'판단 보류');
        if(verdict==='MEMORY_STALE')window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportMemoryStale(reason,target.id);else window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue('ambiguous',reason,target.id);
        showReviewNotice(verdict==='MEMORY_STALE'?'응답 유지 · 기억 확인 필요':'응답 유지 · 근거 불충분',reason,'info',5500);
        return;
      }
      if (verdict==='PASS') {
        markProcessed(target);
        baselineFingerprint = messageFingerprint(target);
        addProcessHistory('PASS');
        setStatus('이상 없음', 'ok');
        showReviewNotice('검토 완료 · 이상 없음','선택한 검사 항목에서 교정할 내용을 찾지 못했습니다.');
        return;
      }
      if(verdict==='CONTINUITY_DRIFT'&&!parsed.replacements.length&&!parsed.refined_text){addProcessHistory(verdict,parsed.reason||'연속성 판단을 확인해 주세요.',{target,verdict});await showCorrectionConfirm({target,corrected:target.content,reason:parsed.reason||'연속성 판단을 확인해 주세요.',parsed});return;}
      if (!parsed.replacements && !parsed.refined_text) throw new Error('Gemini 응답 구조가 교정 형식이 아님');

      const corrected = applyCorrectionUnits(target.content,validateReviewUnits(target.content,parsed));
      if (normalizeCrackLinebreaks(corrected) === normalizeCrackLinebreaks(target.content)) {
        markProcessed(target);
        baselineFingerprint = messageFingerprint(target);
        addProcessHistory('PASS');
        setStatus('변경 없음', 'ok');
        showReviewNotice('검토 완료 · 변경 없음','교정 제안이 원본과 같아 응답을 그대로 유지했습니다.');
        return;
      }
      if (looksLikeUserCopy(corrected, recent)) {
        markProcessed(target);
        baselineFingerprint = messageFingerprint(target);
        addProcessHistory('교정미적용');
        setStatus('유저 입력 복사 감지', 'error');
        showReviewNotice('응답을 유지했어요','교정본이 사용자 입력과 거의 같아 잘못 적용되지 않도록 원본을 유지했습니다.','info',5500);
        return;
      }

      const reason = String(parsed.reason || '교정 필요');
      addProcessHistory(verdict,reason,{target,verdict});
      setStatus(verdict==='CONTINUITY_DRIFT'?'연속성 이탈 · 확인 필요':'응답 오류 · 처리 중');
      if(settings.autoApply){
        const objective=parsed.replacements.filter(unit=>unit.verdict==='RESPONSE_ERROR'&&reviewAutoApplyEligible(target.content,{...parsed,verdict:'RESPONSE_ERROR',replacements:[unit]}));
        if(objective.length){
          const objectiveResult={...parsed,verdict:'RESPONSE_ERROR',replacements:objective};
          const remaining=parsed.replacements.filter(unit=>!objective.includes(unit));
          const appliedTarget=await applyCorrection(target,applyCorrectionUnits(target.content,validateReviewUnits(target.content,objectiveResult)),reason,objectiveResult,{reloadAfter:!remaining.length});
          if(remaining.length){
            const remainingResult={...parsed,replacements:remaining,verdict:remaining.some(unit=>unit.verdict==='CONTINUITY_DRIFT')?'CONTINUITY_DRIFT':'RESPONSE_ERROR'};
            activeReviewTarget=appliedTarget;
            const proposed=applyCorrectionUnits(appliedTarget.content,validateReviewUnits(appliedTarget.content,remainingResult));
            await showCorrectionConfirm({target:appliedTarget,corrected:proposed,reason:reason+' · 확정된 오류는 반영했고 나머지 제안은 확인을 기다립니다.',parsed:remainingResult});
          }
        }else await showCorrectionConfirm({target,corrected,reason,parsed});
      }else await showCorrectionConfirm({target,corrected,reason,parsed});
    } catch (e) {
      addProcessHistory('오류', formatErrorHistory(e));
      setStatus('오류', 'error');
      console.error('[Crack Response Refiner RP Manager]', e);
      if(!force&&activeReviewTarget){
        // The shared transport owns bounded retries and cooldown. Re-enqueueing
        // the same response here used to multiply that retry budget (up to 3 jobs).
        const failedKey=messageAutoKey(activeReviewTarget);
        autoFailureKey=failedKey;autoFailureCount+=1;
        lastAutoAssistantKey=failedKey;
      }
      if(activeReviewTarget){
        const unresolved=reviewGateRows()[String(activeReviewTarget.id)];
        const priorUnresolved=priorReviewGate&&priorReviewGate.fingerprint===messageFingerprint(activeReviewTarget)&&!['settled','unreviewed'].includes(priorReviewGate.status);
        const untouched=aiTransportPending&&!priorUnresolved&&unresolved?.status==='review-running'&&unresolved.fingerprint===messageFingerprint(activeReviewTarget);
        const unreviewed=untouched&&refinerTransportFailure(e);
        setReviewGate(activeReviewTarget,unreviewed?'unreviewed':/STALE/.test(String(e.code||''))?'stale':'error');
        if(force||!unreviewed)showReviewFailure(activeReviewTarget,e);
      }
      window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue(e.code==='STALE_RESPONSE_REVIEW'?'stale':'error',e.message,activeReviewTarget?.id);
      if(e.code!=='RESPONSE_READBACK_UNVERIFIED')showReviewNotice('응답 검토를 마치지 못했어요',String(e.message||e),'error',6000);
    } finally {
      clearInterval(reviewProgressTimer);reviewProgressTimer=0;
      workerBusy = false;activeReviewTarget=null;activeReviewMode='';
      if (badge && !badge.dataset.result) hideReviewNotice();
    }
  }

  function showReviewFailure(target,error) {
    if(error?.code==='RESPONSE_READBACK_UNVERIFIED'){
      showReviewNotice('응답 반영 확인 필요','응답이 반영되지 않았다면 새로고침해 주세요.','error',7000);
      showRefinerRefreshPrompt(String(error.message||error));
      return;
    }
    if(confirmOverlay)return;
    document.getElementById('wish-rpcore-refiner-refresh')?.remove();
    ensureThemeStyles();hideReviewNotice();window.__WISH_RP_MANAGER_AI_BRIDGE__?.hideRefinerPopups();
    const overlay=document.createElement('div');confirmOverlay=overlay;
    overlay.id='wish-rpcore-refiner-confirm';overlay.className='wish-rpcore-refiner-ui';
    overlay.style.cssText='position:fixed;inset:0;z-index:2147483646;background:var(--rr-scrim);display:grid;place-items:center;padding:16px';
    const box=document.createElement('section');box.className='rr-confirm-box rr-failure-box';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-labelledby','rr-failure-title');
    box.innerHTML='<header class="rr-confirm-head"><div class="rr-confirm-heading"><small>WISH · RESPONSE REVIEW</small><h3 id="rr-failure-title">응답 검토를 마치지 못했어요</h3><p>원본 응답은 그대로 유지됩니다.</p></div><button data-close data-rpcm-close="icon" aria-label="닫기">×</button></header><div class="rr-confirm-body"><p data-reason></p></div><footer class="rr-confirm-foot"><div class="rr-confirm-actions"><button data-continue>교정 없이 계속</button><button data-retry class="rr-primary">다시 검수</button></div></footer>';
    setRefinerErrorSummary(box,error);
    const close=()=>{overlay.remove();if(confirmOverlay===overlay){confirmOverlay=null;cancelConfirmation=null;}};
    cancelConfirmation=close;
    box.querySelector('[data-close]').onclick=close;
    box.querySelector('[data-retry]').onclick=()=>{close();setTimeout(()=>runRefiner({force:true,targetOverride:target,maxOutputTokens:error.code==='REVIEW_OUTPUT_LIMIT'?32768:0,reviewMode:error.code==='AI_REQUEST_TIMEOUT'?'normal':''}),0);};
    box.querySelector('[data-continue]').onclick=async()=>{
      try{const fresh=await assertReviewSource(target,getChatId());markProcessed(fresh);addProcessHistory('원본 유지','사용자가 선택한 응답의 교정 없이 계속을 선택했습니다.',{target:fresh});close();setStatus('원본 유지');}catch(e){toast(e.message,'error');}
    };
    overlay.append(box);document.body.append(overlay);resizeRefinerOverlays();
  }

  function renderCorrectionComparison(card,before,after) {
    const a=String(before||''),b=String(after||'');
    const left=card.querySelector('[data-before]'),right=card.querySelector('[data-after]');
    const append=(node,text,changed)=>{if(!text)return;const part=changed?document.createElement('mark'):document.createTextNode(text);if(changed)part.textContent=text;node.append(part);};
    const tokenize=text=>text.match(/[\p{L}\p{N}_]+|\s+|[^\p{L}\p{N}_\s]/gu)||[];
    const aa=tokenize(a),bb=tokenize(b);
    // 큰 전체 응답은 제한된 공통 앞/뒤 비교로 표시해 UI 비용을 제한합니다.
    if(aa.length*bb.length>80000||aa.length+bb.length>2000){
      let start=0,aEnd=a.length,bEnd=b.length;
      while(start<a.length&&start<b.length&&a[start]===b[start])start++;
      while(aEnd>start&&bEnd>start&&a[aEnd-1]===b[bEnd-1]){aEnd--;bEnd--;}
      for(const [node,text,end] of [[left,a,aEnd],[right,b,bEnd]]){append(node,text.slice(0,start),false);append(node,text.slice(start,end),true);append(node,text.slice(end),false);}
    }else{
      const rows=Array.from({length:aa.length+1},()=>new Uint16Array(bb.length+1));
      for(let i=aa.length-1;i>=0;i--)for(let j=bb.length-1;j>=0;j--)rows[i][j]=aa[i]===bb[j]?rows[i+1][j+1]+1:Math.max(rows[i+1][j],rows[i][j+1]);
      let i=0,j=0;
      while(i<aa.length||j<bb.length){
        if(i<aa.length&&j<bb.length&&aa[i]===bb[j]){append(left,aa[i++],false);append(right,bb[j++],false);}
        else if(i<aa.length&&(j===bb.length||rows[i+1][j]>=rows[i][j+1]))append(left,aa[i++],true);
        else append(right,bb[j++],true);
      }
    }
    if(!a)left.textContent='(없음)';if(!b)right.textContent='(없음)';
  }

  function showCorrectionConfirm({target,corrected,reason,parsed=null}) {
    return new Promise(resolve=>{
      clearRefinerConfirmation();document.getElementById('wish-rpcore-refiner-refresh')?.remove();ensureThemeStyles();setReviewGate(target,'review-waiting-user');
      window.__WISH_RP_MANAGER_AI_BRIDGE__?.hideRefinerPopups();
      window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue('proposal',reason,target.id,{screen:false});
      const overlay=document.createElement('div');confirmOverlay=overlay;
      overlay.id='wish-rpcore-refiner-confirm';overlay.className='wish-rpcore-refiner-ui';
      overlay.style.cssText='position:fixed;inset:0;z-index:2147483646;background:var(--rr-scrim);display:flex;align-items:center;justify-content:center;padding:16px';
      const box=document.createElement('section');
      box.className='rr-confirm-box';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-labelledby','rr-confirm-title');
      box.innerHTML=`<header class="rr-confirm-head"><div class="rr-confirm-heading"><small>WISH · RESPONSE REVIEW</small><h3 id="rr-confirm-title">응답 교정 제안</h3><p>원문과 제안을 비교하고 적용할 항목을 선택하세요.</p></div><button type="button" data-close data-rpcm-close="icon" aria-label="닫기">×</button></header>
        <div class="rr-confirm-body"><div class="rr-review-summary"><span data-verdict class="rr-verdict-pill"></span><p data-reason></p></div><p data-stale hidden>검수 중 원문이 바뀌었습니다. 최신 응답을 다시 검수해 주세요.</p>
        <div class="rr-selection-bar"><span data-total-count></span><button data-act="all">전체 선택</button></div><div data-changes></div>
        <details class="rr-preview"><summary>최종 응답 미리보기 · 직접 편집</summary><textarea aria-label="최종 교정 응답"></textarea></details>
        <label class="rr-exception"><input type="checkbox" data-exception> 원본 유지 시 이 검수 유형을 예외로 저장</label>
        <input data-policy hidden aria-label="교정 예외 적용 범위" placeholder="허용할 표현과 적용할 장면을 직접 입력하세요"></div>
        <footer class="rr-confirm-foot"><div class="rr-foot-note"><span data-selection-count></span><span>선택 항목만 반영</span></div><div class="rr-confirm-actions"><button data-act="keep">원본 유지</button><button data-act="apply" class="rr-primary">선택 적용</button><button data-act="memory">기억 검토</button><button data-act="copy">교정본 복사</button><button data-act="review" hidden>최신 응답 다시 검수</button></div></footer>`;
      box.querySelector('[data-reason]').textContent=reason;
      box.querySelector('[data-verdict]').textContent=(REVIEW_VERDICT_LABELS[parsed?.verdict]||'교정 제안')+(parsed?.verdict==='CONTINUITY_DRIFT'?' · 연속성 수정은 직접 확인 후 선택하세요.':'');
      const reviewChatId=getChatId();
      const units=correctionUnits(target.content,parsed||{refined_text:corrected,reason});
      const list=box.querySelector('[data-changes]'),ta=box.querySelector('textarea'),apply=box.querySelector('[data-act="apply"]');
      const checks=units.map((unit,index)=>{
        const card=document.createElement('article');card.className='rr-change-card';
        card.innerHTML='<header class="rr-change-head"><label><input type="checkbox"><strong></strong></label><small data-item-verdict class="rr-change-meta"></small></header><p class="rr-change-reason"></p><div class="rr-compare"><div><small>원문</small><p data-before></p></div><div><small>교정 제안</small><p data-after></p></div></div><details class="rr-evidence"><summary>판정 근거 보기</summary><p></p></details>';
        card.querySelector('strong').textContent=`${index+1}. ${REVIEW_TOPICS[unit.category]?.label||'응답'} 수정`;
        card.querySelector('.rr-change-reason').textContent=unit.reason||reason;
        card.querySelector('[data-item-verdict]').textContent=(REVIEW_VERDICT_LABELS[unit.verdict||parsed?.verdict]||'검토 필요')+' · '+(unit.severity==='confirmed'?'확정 근거':'직접 확인 필요');
        card.querySelector('input').checked=unit.verdict!=='CONTINUITY_DRIFT'&&(unit.verdict||parsed?.verdict)!=='CONTINUITY_DRIFT';
        renderCorrectionComparison(card,unit.from,unit.to);
        card.querySelector('details p').textContent=[unit.evidenceSource,unit.evidence||parsed?.evidence||'근거 출처가 제공되지 않았습니다. 원문과 저장 기억을 직접 확인해 주세요.'].filter(Boolean).join('\n');
        const check=card.querySelector('input');check.onchange=renderSelection;list.append(card);return check;
      });
      box.querySelector('[data-total-count]').textContent=`수정 제안 ${units.length}개`;
      if(!units.length){const empty=document.createElement('p');empty.className='rr-empty-changes';empty.textContent='자동으로 적용할 수정 구간을 찾지 못했습니다. 판정 근거를 확인하고 원본 유지 또는 기억 검토를 선택해 주세요.';list.append(empty);}
      let stale=false,busy=false,edited=false;
      function selected(){return units.filter((_,index)=>checks[index].checked);}
      function renderSelection(){edited=false;ta.value=applyCorrectionUnits(target.content,selected());apply.disabled=stale||!selected().length;checks.forEach(check=>check.closest('article').dataset.selected=String(check.checked));box.querySelector('[data-selection-count]').textContent=`${selected().length} / ${units.length}개 선택`;box.querySelector('[data-act="all"]').textContent=selected().length===units.length&&units.length?'전체 해제':'전체 선택';}
      renderSelection();if(ta.value!==target.content)saveCorrectionArchive(target,ta.value,reason,'검토 제안');
      box.querySelector('[data-act="copy"]').onclick=()=>{saveCorrectionArchive(target,ta.value,reason,'복사용 교정본');copyCorrectionText(ta.value,ta);};
      ta.oninput=()=>{edited=true;box.querySelector('[data-selection-count]').textContent='직접 편집한 응답';apply.disabled=stale||normalizeCrackLinebreaks(ta.value)===normalizeCrackLinebreaks(target.content);};
      const exception=box.querySelector('[data-exception]'),policy=box.querySelector('[data-policy]');exception.onchange=()=>{policy.hidden=!exception.checked;};
      const previousFocus=document.activeElement;
      const onEscape=event=>{if(event.key==='Escape'&&!busy){event.preventDefault();event.stopPropagation();dismiss();}};
      const close=value=>{clearInterval(timer);document.removeEventListener('keydown',onEscape,true);overlay.remove();if(confirmOverlay===overlay){confirmOverlay=null;cancelConfirmation=null;}if(previousFocus?.isConnected)previousFocus.focus?.({preventScroll:true});resolve(value);};
      const dismiss=()=>{if(busy)return;close(false);setStatus('검토 보류');showReviewNotice('교정 검토를 보류했어요','원본은 유지됩니다. 응답 교정에서 다시 검수할 수 있어요.','info');};
      box.querySelector('[data-close]').onclick=dismiss;document.addEventListener('keydown',onEscape,true);
      const markStale=()=>{stale=true;setReviewGate(target,'stale');box.querySelector('[data-stale]').hidden=false;box.querySelector('[data-act="review"]').hidden=false;apply.disabled=true;setStatus('최신 응답 재검수 필요','error');};
      cancelConfirmation=()=>close(false);
      const timer=setInterval(async()=>{if(!overlay.isConnected){clearInterval(timer);return;}try{await assertReviewSource(target,reviewChatId);}catch(error){if(['STALE_RESPONSE_REVIEW','WISH_REFINER_STALE'].includes(error.code))markStale();}},2000);
      box.querySelector('[data-act="all"]').onclick=()=>{if(busy)return;const selectAll=selected().length!==units.length;checks.forEach(check=>check.checked=selectAll);renderSelection();};
      box.querySelector('[data-act="review"]').onclick=()=>{if(busy)return;close(false);setTimeout(()=>runRefiner({force:true}),0);};
      const keep=async memory=>{
        if(busy)return;
        try{
          await assertReviewSource(target,reviewChatId);
          if(exception.checked){const text=policy.value.trim();if(!text)throw new Error('예외 정책의 적용 범위를 직접 입력해 주세요.');settings.exceptions=[...(settings.exceptions||[]),{id:Date.now().toString(36),text,enabled:true,createdAt:Date.now()}];saveSettings();}
          if(memory)window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportMemoryStale(reason+' · '+String(parsed?.evidence||''),target.id);
          markProcessed(target);baselineFingerprint=messageFingerprint(target);addProcessHistory(memory?'기억 검토 필요':'원본 유지',reason,{target});setStatus('원본 유지');close(false);showReviewNotice('응답을 유지했어요','교정을 적용하지 않고 원본으로 계속합니다.','info');
        }catch(error){if(['STALE_RESPONSE_REVIEW','WISH_REFINER_STALE'].includes(error.code))markStale();toast(error.message,'error');}
      };
      box.querySelector('[data-act="keep"]').onclick=()=>keep(false);box.querySelector('[data-act="memory"]').onclick=()=>keep(true);
      apply.onclick=async()=>{
        if(stale||busy)return;busy=true;for(const control of box.querySelectorAll('input,textarea,button'))control.disabled=true;apply.textContent='서버 반영 중…';
        try{const chosen=selected();await applyCorrection(target,ta.value,reason,edited?null:{...parsed,replacements:chosen});close(true);}
        catch(error){addProcessHistory('오류',formatErrorHistory(error),{target});window.__WISH_RP_MANAGER_AI_BRIDGE__?.reportRefinerIssue(error.code==='STALE_RESPONSE_REVIEW'?'stale':'error',error.message,target.id);if(['STALE_RESPONSE_REVIEW','WISH_REFINER_STALE'].includes(error.code))markStale();toast(error.message,'error');}
        finally{busy=false;for(const control of box.querySelectorAll('input,textarea,button'))control.disabled=false;apply.disabled=stale||(edited?normalizeCrackLinebreaks(ta.value)===normalizeCrackLinebreaks(target.content):!selected().length);apply.textContent='선택 적용';}
      };
      overlay.append(box);document.body.append(overlay);resizeRefinerOverlays();setStatus('사용자 확인 대기');
      hideReviewNotice();box.querySelector('[data-close]').focus({preventScroll:true});

    });
  }

  function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

  function scheduleAutoCheck(delay=1200) {
    if (!settings.enabled || !autoBaselineReady) return;
    autoCheckQueued=true;
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(async () => {
      debounceTimer=null;
      if(!settings.enabled||!autoBaselineReady||document.hidden)return;
      if(workerBusy||confirmOverlay||autoScanBusy){scheduleAutoCheck(1200);return;}
      autoScanBusy=true;autoCheckQueued=false;
      const epoch=autoPrimeEpoch,roomKey=chatStateKey();let retry=false;
      try {
        const latest=await findLastAssistant();
        if(epoch!==autoPrimeEpoch||roomKey!==chatStateKey())return;
        const latestKey=messageAutoKey(latest);
        if(!latestKey||latestKey===lastAutoAssistantKey)return;
        if(isProcessed(latest)){lastAutoAssistantKey=latestKey;return;}
        const target = await waitStableAssistant();
        if(epoch!==autoPrimeEpoch||roomKey!==chatStateKey())return;
        if (!target){retry=++autoCheckWaits<=6;return;}
        const autoKey = messageAutoKey(target);
        if (!autoKey || autoKey === lastAutoAssistantKey) return;
        autoCheckWaits=0;
        // 검수 시작 표시는 runRefiner가 실제 대상 검수를 시작할 때만 기록합니다.
        // 대기/진행 중에 발견된 다음 응답은 큐에 남겨 조용해진 뒤에도 확인합니다.
        await runRefiner({ force: false, targetOverride: target });
      } catch (error) {
        retry=error.code!=='CRACK_AUTH_REQUIRED'&&++autoCheckWaits<=6;
        if(!retry){console.warn('[Wish Response Refiner] 자동 완료 확인 실패',error);showReviewNotice('자동 검토를 시작하지 못했어요',String(error.message||error)+' · 최근 AI 응답 재검수를 눌러 주세요.','error',6000);}
      } finally {
        autoScanBusy=false;
        if(epoch===autoPrimeEpoch&&roomKey===chatStateKey()&&(autoCheckQueued||retry))scheduleAutoCheck(retry?2500:1200);
      }
    }, Math.max(0,Number(delay)||0));
  }

  async function primeBaseline() {
    const epoch = ++autoPrimeEpoch;
    autoBaselineReady = false;
    try {
      const last = await findLastAssistant();
      if (epoch !== autoPrimeEpoch) return;
      const pending=/^(streaming|generating|pending|in_progress)$/i.test(String(last?.raw?.status||''))||refinerGenerationVisible();
      baselineFingerprint = pending?'':messageFingerprint(last);
      lastAutoAssistantKey = pending?'':messageAutoKey(last);
      autoCheckQueued=pending;autoCheckWaits=0;
      if(last&&!pending&&!reviewGateRows()[String(last.id)])setReviewGate(last,'settled');
    } catch (_) {
      if (epoch !== autoPrimeEpoch) return;
      baselineFingerprint = '';
      lastAutoAssistantKey = '';
    } finally {
      if (epoch === autoPrimeEpoch){autoBaselineReady=true;if(autoCheckQueued)scheduleAutoCheck();}
    }
  }

  function handleRouteBaselineChange() {
    runEpoch++;cancelConfirmation?.();cancelConfirmation=null;closeSettings();
    lastKnownPath = location.href;
    clearTimeout(debounceTimer);autoCheckQueued=false;autoCheckWaits=0;lastAutoHeartbeatAt=0;
    autoBaselineReady = false;
    void primeBaseline();
  }

  function startObserver() {
    mutationObserver?.disconnect();
    let observedSuiteScope=WSUITE.host?.refinerScope?.();
    mutationObserver = new MutationObserver(mutations => {
      if(document.hidden)return;
      if (location.href !== lastKnownPath || observedSuiteScope!==WSUITE.host?.refinerScope?.()) {
        // Update the observed scope before resetting; subsequent mutations from
        // the same SPA transition must not repeatedly fetch and invalidate it.
        observedSuiteScope=WSUITE.host?.refinerScope?.();
        handleRouteBaselineChange();
        return;
      }
      const own=node=>{const el=node?.nodeType===Node.ELEMENT_NODE?node:node?.parentElement;return !!el?.closest?.('[id^="rpcm-"],[id^="wish-rpcore-"],script,style');};
      if(mutations.every(m=>own(m.target)||(m.type==='childList'&&[...m.addedNodes,...m.removedNodes].every(own))))return;
      scheduleAutoCheck();
    });
    mutationObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
    setInterval(() => {
      if (location.href !== lastKnownPath || observedSuiteScope!==WSUITE.host?.refinerScope?.()) {observedSuiteScope=WSUITE.host?.refinerScope?.();handleRouteBaselineChange(); return; }
      if(document.hidden||!settings.enabled||!autoBaselineReady)return;
      const heartbeatDue=Date.now()-lastAutoHeartbeatAt>=6000;
      if((autoCheckQueued||heartbeatDue)&&!debounceTimer&&!autoScanBusy){lastAutoHeartbeatAt=Date.now();scheduleAutoCheck(autoCheckQueued?0:180);}
    }, 1500);
    // 백그라운드 탭에서 응답 생성이 끝나면 MutationObserver 콜백이 의도적으로 건너뛰어집니다.
    // 다시 탭을 열 때 큐 플래그가 없더라도 최신 응답을 한 번 확인해 누락을 복구합니다.
    document.addEventListener('visibilitychange',()=>{if(!document.hidden&&settings.enabled&&autoBaselineReady){lastAutoHeartbeatAt=Date.now();scheduleAutoCheck(0);}});
  }

  function makeToggle(label, desc, value, onChange) {
    const row = document.createElement('label');
    row.className='rr-settings-toggle';
    row.style.cssText = 'display:flex;gap:16px;align-items:center;padding:14px 0;border-bottom:1px solid var(--rr-line2);cursor:pointer;';
    const text = document.createElement('div');
    text.style.flex = '1';
    text.innerHTML = `<div style="font-size:13px;font-weight:600;color:var(--rr-fg);"></div><div style="font-size:11px;color:var(--rr-muted);margin-top:2px;line-height:1.4;"></div>`;
    text.children[0].textContent = label;
    text.children[1].textContent = desc;
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = !!value;
    input.style.cssText = 'width:18px;height:18px;accent-color:var(--rr-accent);';
    input.onchange = () => onChange(input.checked);
    row.append(text, input);
    return row;
  }

  function formLabel(text) {
    const l = document.createElement('div');
    l.textContent = text;
    l.className='rr-settings-label';
    l.style.cssText = 'font-size:12px;color:var(--rr-fg2);font-weight:600;margin:12px 0 5px;';
    return l;
  }

