  try {
    GM_registerMenuCommand('🪽 응답교정 설정 열기', openSettings);
    GM_registerMenuCommand('최근 AI 응답 재검수', () => runRefiner({ force: true }));
  } catch (_) {}

  async function init() {
    ensureThemeStyles();
    restoreConnectionState();
    createUi();
    await primeBaseline();
    startObserver();
    setStatus(settings.enabled ? '대기' : '꺼짐');
    if (badge) badge.style.display = 'none';
    console.log(`[Wish Response Refiner RP Manager OPTIONAL v1.3.6] loaded · DB=${WISH_DB_NAME} · model=${currentModelId()} · provider=${settings.provider}`);
  }



  WSUITE.coreRefiner={version:'1.3.6-manager-0.15.7',open:openSettings,run:runRefiner,getState:()=>({enabled:settings.enabled,busy:workerBusy,status:currentStatus}),clearProcessed:()=>{saveProcessedSet(new Set());return primeBaseline();}};
